INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C1','kor',5,2,'u4',1,'같은 문제, 서로 다른 의견 — 사람마다 생각과 겪은 일이 달라 한 가지 문제에 여러 의견이 나오는 것은 자연스럽다',ARRAY['6국01-06 듣기·말하기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C2','kor',5,2,'u4',1,'토의의 뜻 — 여럿이 함께 문제를 풀 방법을 찾는 말하기로, 누가 이기는지 겨루는 자리가 아니다',ARRAY['6국01-06 듣기·말하기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C3','kor',5,2,'u4',1,'의견 조정의 뜻 — 서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일로, 내 의견을 버리는 것이 아니다',ARRAY['6국01-06 듣기·말하기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C4','kor',5,2,'u4',1,'의견과 까닭 — 의견에는 그렇게 생각한 까닭이 함께 있어야 다른 의견과 견주어 따져 볼 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C5','kor',5,2,'u4',1,'단원의 흐름 — 의견을 조정하는 방법 알기 → 모둠 토의 → 학급 토의 → 주변의 문제 토의 → 우리 학교 문제 실천',ARRAY['6국01-06 듣기·말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C6','kor',5,2,'u4',2,'토의 대화에서 문제와 의견 찾기 — 사회자가 밝힌 풀려는 문제와 친구들이 제안한 의견, 그 까닭을 찾으며 읽는다',ARRAY['6국01-06 듣기·말하기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C7','kor',5,2,'u4',2,'검토 기준 마련하기 — 의견을 조정할 때 먼저 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 같은 기준을 함께 정한다',ARRAY['6국01-06 듣기·말하기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C8','kor',5,2,'u4',2,'기준은 문제마다 — 문제에 따라 기준을 다르게 정하거나 비용처럼 새 기준을 더할 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C9','kor',5,2,'u4',2,'장점과 단점 검토하기 — 정한 기준에 비추어 의견을 실천했을 때 기대되는 효과와 생길 수 있는 문제를 정리한다',ARRAY['6국01-06 듣기·말하기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C10','kor',5,2,'u4',2,'단점 말하기는 비난이 아니에요 — 단점을 따지는 것은 최선의 의견을 찾는 과정이므로, 사람이 아니라 의견을 두고 배려하며 말한다',ARRAY['6국01-06 듣기·말하기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C11','kor',5,2,'u4',2,'합의점 찾기 — 서로 조금씩 양보해 의견이 하나로 모이는 자리로, 장점은 살리고 단점은 보완해 찾는다',ARRAY['6국01-06 듣기·말하기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C12','kor',5,2,'u4',2,'합의점의 여러 모습 — 한 의견을 고르는 것뿐 아니라 새 의견을 만들거나 두 의견을 합치거나 둘 이상을 함께 고를 수도 있다',ARRAY['6국01-06 듣기·말하기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C13','kor',5,2,'u4',2,'오가는 조정 차례 — 기준 마련 → 장단점 검토 → 합의점 찾기는 고정된 길이 아니라 필요하면 앞 차례로 되돌아가 다시 따진다',ARRAY['6국01-06 듣기·말하기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C14','kor',5,2,'u4',2,'손을 들어 정할 때와 토의의 목적 — 끝내 합의가 어려우면 많은 쪽으로 정하기도 하지만, 토의의 목적은 의견을 조정해 합의점을 찾는 데 있다',ARRAY['6국01-06 듣기·말하기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C15','kor',5,2,'u4',4,'토의 주제 정하기 — 불평이나 탓하는 말이 아니라 「어떻게 하면 ~할까?」처럼 함께 방법을 찾는 물음으로 정한다',ARRAY['6국01-06 듣기·말하기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C16','kor',5,2,'u4',4,'주제를 고르는 기준 — 우리와 관련이 있고, 우리가 직접 풀 수 있고, 가장 먼저 풀어야 할 문제를 고른다',ARRAY['6국01-06 듣기·말하기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C17','kor',5,2,'u4',4,'질문하며 듣기 — 친구 의견을 들으며 궁금한 점을 질문하면 의견이 또렷해지고 빈틈을 보완할 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C18','kor',5,2,'u4',4,'공손한 질문 — 질문은 친구를 이기려는 공격이 아니라 「궁금해서 묻는데」처럼 의견을 함께 다듬으려는 물음이다',ARRAY['6국01-03 듣기·말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C19','kor',5,2,'u4',4,'모둠 의견으로 고치기 — 기준에 따라 의견마다 장단점을 정리하고, 장점을 살려 모두가 동의할 만한 하나의 의견으로 고친다',ARRAY['6국01-06 듣기·말하기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C20','kor',5,2,'u4',4,'참여의 가치 — 내 의견이 그대로 뽑히지 않아도 말하고 질문하며 함께 고친 과정 속에 내 생각이 들어 있다',ARRAY['6국01-06 듣기·말하기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C21','kor',5,2,'u4',4,'맞장구만 치면 — 모두 좋다고만 하면 단점을 따지는 과정이 빠져 실천할 때 생길 문제를 미리 찾지 못한다',ARRAY['6국01-06 듣기·말하기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C22','kor',5,2,'u4',6,'사회자의 일 — 사회자는 절차를 안내하고 나온 의견을 정리하며 여러 사람이 말하도록 돕는다',ARRAY['6국01-06 듣기·말하기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C23','kor',5,2,'u4',6,'학급 토의 절차 — 토의 주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기 차례로 한다',ARRAY['6국01-06 듣기·말하기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C24','kor',5,2,'u4',6,'의견 모으기 안의 조정 — 의견 모으기 안에 검토 기준 마련하기 · 장점과 단점 검토하기 · 합의점 찾기가 들어 있다',ARRAY['6국01-06 듣기·말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C25','kor',5,2,'u4',6,'칠판에 한눈에 — 의견이 많으면 칠판이나 화면에 의견과 기준, 장단점을 정리해 모두가 한눈에 보고 견준다',ARRAY['6국01-06 듣기·말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C26','kor',5,2,'u4',6,'모두가 참여하는 학급 토의 — 반 전체의 문제이므로 모두가 의견을 마련하고, 몇몇 친구의 의견만 중심이 되지 않게 여러 친구가 말한다',ARRAY['6국01-06 듣기·말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C27','kor',5,2,'u4',6,'회의와 토의 — 회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 의견을 조정해 합의된 쪽으로 정한다',ARRAY['6국01-06 듣기·말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C28','kor',5,2,'u4',6,'정한 의견 받아들이고 실천하기 — 정당한 절차로 정한 의견은 내 의견과 달라도 함께 실천하고, 해 보니 잘 안 되면 다시 토의해 고친다',ARRAY['6국01-06 듣기·말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C29','kor',5,2,'u4',8,'서로 다른 가치 — 사람마다 소중히 여기는 것이 달라서, 한쪽의 소중한 일이 다른 쪽에게 불편이 되어 부딪칠 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C30','kor',5,2,'u4',8,'존중과 양보 — 서로 다른 가치는 둘 다 소중할 수 있어 누가 옳은지 겨루기보다 서로 존중하며 조금씩 양보할 방법을 찾는다',ARRAY['6국01-06 듣기·말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C31','kor',5,2,'u4',8,'주변의 문제를 토의 주제로 — 주변의 부딪침 가운데 풀어야 할 필요가 있고 우리가 풀이에 도움을 줄 수 있는 문제를 고른다',ARRAY['6국01-06 듣기·말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C32','kor',5,2,'u4',8,'자료로 의견 다듬기 — 까닭은 타당하고 구체적이어야 하므로 책이나 누리집에서 자료를 찾아 의견을 다듬는다',ARRAY['6국01-06 듣기·말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C33','kor',5,2,'u4',8,'정한 의견 제안하기 — 우리가 정한 의견을 누구에게 어떻게 알릴지 정해, 의견과 까닭을 알맞은 곳에 제안한다',ARRAY['6국01-06 듣기·말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C34','kor',5,2,'u4',11,'학교 문제 토의 여섯 단계 — 토의 주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기 → 되돌아보기',ARRAY['6국01-06 듣기·말하기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C35','kor',5,2,'u4',11,'이견이 없는지 확인하기 — 의견을 정한 뒤에는 다른 생각이 남아 있지 않은지 확인해야 모두가 함께 실천할 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C36','kor',5,2,'u4',11,'합의점을 찾는 생각 도구 — 막힐 때 바꾸기 · 합치기 · 줄이기와 빼기 · 순서 바꾸기 물음을 던져 새 의견을 떠올린다',ARRAY['6국01-06 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C37','kor',5,2,'u4',11,'토의 되돌아보기 — 잘한 점과 보완할 점을 나누되 누구 잘못인지 따지기보다 다음에 함께 노력할 점을 찾는다',ARRAY['6국01-06 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C38','kor',5,2,'u4',13,'정답 의견은 없어요 — 처음부터 정해진 정답 의견은 없고, 견주고 질문하고 고치는 과정에서 처음보다 나아진 의견이 만들어진다',ARRAY['6국01-06 듣기·말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C39','kor',5,2,'u4',13,'순화어 — 지나치게 어려운 말이나 외래어를 알기 쉬운 우리말로 바꾼 말로, 언박싱 → 개봉 · 북 트레일러 → 책 소개 영상 · 큐레이터 → 전시 기획자 · 팩트 체크 → 사실 확인 · 여행 가이드 → 여행 안내원처럼 쓴다 (기초 다지기)',ARRAY['기초 다지기(순화어)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X01','kor',5,'u4',ARRAY['K5-2-u4-C1']::text[],'같은 문제에 의견이 서로 다르면 누군가 잘못 생각한 것이라고 여긴다','다른 게 자연스러워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X02','kor',5,'u4',ARRAY['K5-2-u4-C2']::text[],'토의를 누가 이기는지 겨루는 말하기로 여긴다','함께 방법 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X03','kor',5,'u4',ARRAY['K5-2-u4-C3','K5-2-u4-C11']::text[],'의견을 조정하면 내 의견은 모두 버려야 하거나 진 것이라고 여긴다','살리고 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X04','kor',5,'u4',ARRAY['K5-2-u4-C4']::text[],'까닭 없이 의견만 말하거나 「그냥 좋아서」로 의견을 고른다','까닭이 있어야 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X05','kor',5,'u4',ARRAY['K5-2-u4-C5']::text[],'단원에서 배우는 차례를 섞거나 학교 문제 실천부터 한다고 여긴다','방법 → 모둠 → 학급 → 주변 → 학교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X06','kor',5,'u4',ARRAY['K5-2-u4-C6']::text[],'토의 대화에서 의견만 찾고 풀려는 문제나 누가 무슨 까닭을 들었는지 놓친다','문제 · 의견 · 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X07','kor',5,'u4',ARRAY['K5-2-u4-C7']::text[],'검토 기준을 정하지 않고 바로 마음에 드는 의견을 고른다','기준이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X08','kor',5,'u4',ARRAY['K5-2-u4-C7','K5-2-u4-C22']::text[],'목소리 크기나 먼저 말한 차례, 말한 사람을 의견을 견주는 기준으로 여긴다','의견을 기준으로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X09','kor',5,'u4',ARRAY['K5-2-u4-C8']::text[],'검토 기준은 어떤 문제든 늘 똑같은 세 가지뿐이라고 여긴다','문제마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X10','kor',5,'u4',ARRAY['K5-2-u4-C9']::text[],'좋은 의견에는 단점이 없다고 여기거나 단점이 하나라도 있으면 의견을 통째로 버린다','장점과 단점이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X11','kor',5,'u4',ARRAY['K5-2-u4-C10']::text[],'단점 말하기를 친구를 비난하는 일로 여겨 피하거나, 의견이 아니라 친구를 깎아내린다','사람 말고 의견을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X12','kor',5,'u4',ARRAY['K5-2-u4-C12']::text[],'합의점은 여러 의견 가운데 하나를 그대로 고르는 것뿐이라고 여긴다','합치고 새로 만들기도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X13','kor',5,'u4',ARRAY['K5-2-u4-C13']::text[],'조정 차례는 한 방향으로만 가서 앞 차례로 되돌아갈 수 없다고 여긴다','필요하면 되돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X14','kor',5,'u4',ARRAY['K5-2-u4-C14']::text[],'손을 들어 정하면 그 전의 토의는 헛수고라고 여기거나 처음부터 손을 들면 된다고 여긴다','목적은 합의점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X15','kor',5,'u4',ARRAY['K5-2-u4-C15']::text[],'토의 주제를 불평이나 누구 탓인지 묻는 말로 정한다','어떻게 하면 ~할까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X16','kor',5,'u4',ARRAY['K5-2-u4-C16']::text[],'우리와 관련 없거나 우리가 풀 수 없는 문제, 재미만 있는 문제를 주제로 고른다','관련 · 실천 · 시급') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X17','kor',5,'u4',ARRAY['K5-2-u4-C17']::text[],'친구 의견을 듣기만 하고 궁금한 점을 묻지 않거나 질문을 토의를 방해하는 일로 여긴다','물으면 또렷해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X18','kor',5,'u4',ARRAY['K5-2-u4-C18']::text[],'질문을 친구를 이기거나 놀리는 공격처럼 한다','궁금해서 묻는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X19','kor',5,'u4',ARRAY['K5-2-u4-C19']::text[],'모둠 의견을 정할 때 한 의견만 남기고 다른 의견의 장점은 버린다','장점을 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X20','kor',5,'u4',ARRAY['K5-2-u4-C20']::text[],'내 의견이 그대로 뽑히지 않으면 토의에서 졌다고 여긴다','내 생각도 들어 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X21','kor',5,'u4',ARRAY['K5-2-u4-C21']::text[],'모두 좋다고 맞장구만 치면 좋은 토의라고 여긴다','따져야 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X22','kor',5,'u4',ARRAY['K5-2-u4-C22']::text[],'사회자는 자기 마음에 드는 의견으로 정해 주는 사람이라고 여긴다','안내하고 정리해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X23','kor',5,'u4',ARRAY['K5-2-u4-C23']::text[],'학급 토의 절차의 차례를 섞거나 한 절차를 빠뜨린다','주제 → 마련 → 나누기 → 모으기 → 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X24','kor',5,'u4',ARRAY['K5-2-u4-C24']::text[],'의견 조정하기가 학급 토의 절차의 어디에 드는지 모르고 다른 절차에 넣는다','의견 모으기 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X25','kor',5,'u4',ARRAY['K5-2-u4-C25']::text[],'의견이 많아도 정리하지 않고 말로만 오가게 둔다','칠판에 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X26','kor',5,'u4',ARRAY['K5-2-u4-C26']::text[],'학급 토의는 몇몇 친구만 말하고 나머지는 듣기만 하면 된다고 여긴다','모두가 참여') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X27','kor',5,'u4',ARRAY['K5-2-u4-C27']::text[],'회의와 토의는 정하는 방법이 똑같다고 여기거나 토의도 늘 손을 들어 바로 정한다고 여긴다','토의는 조정으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X28','kor',5,'u4',ARRAY['K5-2-u4-C28']::text[],'정한 의견이 내 의견과 다르면 따르지 않거나, 한 번 정하면 절대 바꿀 수 없다고 여긴다','함께 실천, 다시 토의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X29','kor',5,'u4',ARRAY['K5-2-u4-C29']::text[],'소중히 여기는 것이 달라 부딪치면 한쪽을 나쁜 사람으로 여긴다','서로 다른 가치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X30','kor',5,'u4',ARRAY['K5-2-u4-C30']::text[],'서로 다른 가치가 부딪치면 더 옳은 한쪽만 골라 이기게 해야 한다고 여긴다','존중하고 양보해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X31','kor',5,'u4',ARRAY['K5-2-u4-C31']::text[],'주변의 문제는 어른들만 풀 수 있어 어린이와 관계없다고 여긴다','우리도 도울 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X32','kor',5,'u4',ARRAY['K5-2-u4-C32']::text[],'자료를 찾지 않고 짐작만으로 까닭을 대거나 크게 말하면 타당해진다고 여긴다','자료로 다듬어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X33','kor',5,'u4',ARRAY['K5-2-u4-C33']::text[],'정한 의견을 누구에게 어떻게 알릴지 정하지 않고 「알린다」로만 끝낸다','누구에게 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X34','kor',5,'u4',ARRAY['K5-2-u4-C35']::text[],'의견을 정한 뒤 다른 생각이 남아 있는지 확인하지 않는다','이견 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X35','kor',5,'u4',ARRAY['K5-2-u4-C34']::text[],'학교 문제 토의에서 되돌아보기를 빼먹거나 여섯 단계의 차례를 섞는다','마지막은 되돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X36','kor',5,'u4',ARRAY['K5-2-u4-C36']::text[],'합의점이 막히면 생각 도구를 쓰지 않고 포기하거나 한 의견만 고른다','바꾸기 · 합치기 · 빼기 · 순서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X37','kor',5,'u4',ARRAY['K5-2-u4-C37']::text[],'토의 되돌아보기를 누구 잘못인지 따지는 시간으로 여긴다','함께 노력할 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X38','kor',5,'u4',ARRAY['K5-2-u4-C38']::text[],'토의에는 처음부터 정해진 정답 의견이 있어 그것을 맞히기만 하면 된다고 여긴다','과정에서 나아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X39','kor',5,'u4',ARRAY['K5-2-u4-C39']::text[],'외래어와 순화어를 짝짓지 못하거나 순화어 쓰기를 장난스럽게 여긴다','누구나 알기 쉬운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#1','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C2',1,'mc','auto','여럿이 함께 문제를 풀 방법을 찾는 말하기를 무엇이라고 하나요?',ARRAY['K5-2-u4-X02','K5-2-u4-X06']::text[],false,'{"seq":1,"concept":"K5-2-u4-C2","difficulty":1,"kind":"mc","stem":"여럿이 함께 문제를 풀 방법을 찾는 말하기를 무엇이라고 하나요?","options":[{"t":"토의","correct":true},{"t":"토론","mis":"K5-2-u4-X02"},{"t":"연설","mis":"K5-2-u4-X02"},{"t":"면담","mis":"K5-2-u4-X06"}],"explanation":["토론은 찬성과 반대로 맞서는 말하기예요.","여러 사람 앞에서 혼자 주장하는 말이에요.","함께 방법을 찾는 말하기는 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#2','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C3',1,'mc','auto','서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일을 무엇이라고 하나요?',ARRAY['K5-2-u4-X03','K5-2-u4-X08','K5-2-u4-X14']::text[],false,'{"seq":2,"concept":"K5-2-u4-C3","difficulty":1,"kind":"mc","stem":"서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일을 무엇이라고 하나요?","options":[{"t":"의견 조정","correct":true},{"t":"의견 버리기","mis":"K5-2-u4-X03"},{"t":"목소리 겨루기","mis":"K5-2-u4-X08"},{"t":"손들기 놀이","mis":"K5-2-u4-X14"}],"explanation":["내 의견을 버리는 일이 아니에요.","목소리로 정하지 않아요.","견주고 고쳐 가는 일이 의견 조정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#3','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C1',1,'mc','auto','두 대표가 함께 풀려고 하는 문제는 무엇인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X16']::text[],false,'{"seq":3,"concept":"K5-2-u4-C1","difficulty":1,"kind":"mc","stem":"두 대표가 함께 풀려고 하는 문제는 무엇인가요?","options":[{"t":"비 오는 날 체육관을 쓰는 방법","correct":true},{"t":"급식 차례를 바꾸는 방법","mis":"K5-2-u4-X06"},{"t":"교실 청소 당번을 정하는 방법","mis":"K5-2-u4-X06"},{"t":"새 체육관을 짓는 방법","mis":"K5-2-u4-X16"}],"explanation":["두 대표의 말에 없어요.","두 대표의 말에 없어요.","두 대표 모두 비 오는 날 체육관 이야기를 했어요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#4','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C1',1,'ox','auto','같은 문제에 서로 다른 의견이 나오는 것은 자연스러운 일이에요.',ARRAY['K5-2-u4-X01']::text[],false,'{"seq":4,"concept":"K5-2-u4-C1","difficulty":1,"kind":"ox","stem":"같은 문제에 서로 다른 의견이 나오는 것은 자연스러운 일이에요.","answer":"O","reason_options":[{"t":"사람마다 생각과 겪은 일이 달라 여러 의견이 나올 수 있기 때문에","correct":true},{"t":"의견이 다르면 누군가 잘못 생각한 것이기 때문에","mis":"K5-2-u4-X01"}],"mis":"K5-2-u4-X01","explanation":["생각은 저마다 달라요.","틀린 쪽이 있는 것이 아니에요.","다른 의견은 자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#5','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C4',2,'mc','auto','저학년 대표가 든 까닭은 무엇인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X04']::text[],false,'{"seq":5,"concept":"K5-2-u4-C4","difficulty":2,"kind":"mc","stem":"저학년 대표가 든 까닭은 무엇인가요?","options":[{"t":"모든 학년이 고르게 쓸 수 있어서","correct":true},{"t":"큰 학년이 질서를 잘 지켜서","mis":"K5-2-u4-X06"},{"t":"저학년이 먼저 와서","mis":"K5-2-u4-X04"},{"t":"체육관이 너무 좁아서","mis":"K5-2-u4-X06"}],"explanation":["고학년 대표의 까닭이에요.","말하지 않은 까닭이에요.","고르게 쓰자는 까닭을 들었어요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#6','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C7',2,'mc','auto','의견을 견주는 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X07']::text[],false,'{"seq":6,"concept":"K5-2-u4-C7","difficulty":2,"kind":"mc","stem":"의견을 견주는 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"목소리가 가장 큰 사람의 의견인가?","correct":true},{"t":"우리가 실천할 수 있는 방법인가?","mis":"K5-2-u4-X07"},{"t":"문제를 푸는 데 효과가 있는 방법인가?","mis":"K5-2-u4-X07"},{"t":"여러 사람에게 도움이 되는 방법인가?","mis":"K5-2-u4-X07"}],"explanation":["알맞은 기준이에요.","알맞은 기준이에요.","목소리 크기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#7','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C5',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C5","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"의견 조정 방법","r":"토의 대화를 보며 차례 알기"},{"l":"학급 토의","r":"반 전체가 절차에 따라 정하기"},{"l":"주변의 문제","r":"서로 다른 가치를 존중하며 풀기"}],"mis":"K5-2-u4-X05","explanation":["방법부터 알아요.","반 전체가 함께해요.","교실 밖 문제까지 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#8','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C2',2,'error','auto','두 의견을 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X04','K5-2-u4-X03']::text[],false,'{"seq":8,"concept":"K5-2-u4-C2","difficulty":2,"kind":"error","stem":"두 의견을 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「어느 쪽이 이기는지 끝까지 겨뤄 보자.」","correct":true,"mis_target":"K5-2-u4-X02"},{"t":"「두 의견의 까닭을 먼저 들어 보자.」","mis":"K5-2-u4-X04"},{"t":"「모두가 기분 좋게 쓸 방법을 함께 찾자.」","mis":"K5-2-u4-X03"}],"explanation":["까닭부터 들어요.","함께 찾는 자리예요.","토의는 겨루는 자리가 아니에요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#9','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C3',2,'mc','auto','의견을 조정한다는 것에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X08','K5-2-u4-X01']::text[],false,'{"seq":9,"concept":"K5-2-u4-C3","difficulty":2,"kind":"mc","stem":"의견을 조정한다는 것에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로의 의견을 견주어 모두가 받아들일 만한 쪽으로 고쳐 가는 것","correct":true},{"t":"한쪽 의견을 무조건 버리는 것","mis":"K5-2-u4-X03"},{"t":"목소리가 큰 쪽을 따르는 것","mis":"K5-2-u4-X08"},{"t":"의견이 다르면 토의를 그만두는 것","mis":"K5-2-u4-X01"}],"explanation":["버리는 것이 아니에요.","목소리로 정하지 않아요.","견주고 고쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#10','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C4',3,'mc','auto','「그냥 좋아서요.」라고만 말한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X04','K5-2-u4-X01','K5-2-u4-X08']::text[],false,'{"seq":10,"concept":"K5-2-u4-C4","difficulty":3,"kind":"mc","stem":"「그냥 좋아서요.」라고만 말한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 의견이 좋은 까닭을 함께 말해 주면 견주기 쉬워.」","correct":true},{"t":"「좋으면 됐지, 까닭은 필요 없어.」","mis":"K5-2-u4-X04"},{"t":"「네 의견은 틀렸으니 다시 말해.」","mis":"K5-2-u4-X01"},{"t":"「목소리를 더 크게 하면 뽑힐 거야.」","mis":"K5-2-u4-X08"}],"explanation":["까닭이 있어야 견줘요.","틀린 의견이 아니에요.","까닭을 함께 말하도록 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#1','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C3',2,'ox','auto','의견을 조정하면 내 의견은 모두 버려야 해요.',ARRAY['K5-2-u4-X03']::text[],false,'{"seq":1,"concept":"K5-2-u4-C3","difficulty":2,"kind":"ox","stem":"의견을 조정하면 내 의견은 모두 버려야 해요.","answer":"X","reason_options":[{"t":"장점은 살리고 단점은 보완해 더 나은 의견으로 고쳐 가는 것이기 때문에","correct":true},{"t":"모두의 의견을 들으려면 내 생각은 없어야 하기 때문에","mis":"K5-2-u4-X03"}],"mis":"K5-2-u4-X03","explanation":["버리지 않아요.","내 생각도 함께 들어가요.","살리고 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#2','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C5',2,'mc','auto','이 단원에서 의견을 조정하는 방법을 안 다음에 하는 활동은 어느 것인가요?',ARRAY['K5-2-u4-X05']::text[],false,'{"seq":2,"concept":"K5-2-u4-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 의견을 조정하는 방법을 안 다음에 하는 활동은 어느 것인가요?","options":[{"t":"모둠에서 의견을 조정하며 토의하기","correct":true},{"t":"우리 학교 문제 실천을 맨 먼저 하기","mis":"K5-2-u4-X05"},{"t":"표준어와 방언 알아보기","mis":"K5-2-u4-X05"},{"t":"방언 지도 만들기","mis":"K5-2-u4-X05"}],"explanation":["실천은 맨 끝이에요.","지난 단원이에요.","방법 다음은 모둠 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#3','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C1',3,'mc','auto','「의견이 서로 다르니 이 토의는 실패야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X01','K5-2-u4-X08','K5-2-u4-X26']::text[],false,'{"seq":3,"concept":"K5-2-u4-C1","difficulty":3,"kind":"mc","stem":"「의견이 서로 다르니 이 토의는 실패야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「생각이 다른 게 자연스러우니 견주어 보며 더 나은 방법을 찾자.」","correct":true},{"t":"「맞아, 의견이 다르면 토의할 필요가 없어.」","mis":"K5-2-u4-X01"},{"t":"「목소리 큰 쪽으로 빨리 정하자.」","mis":"K5-2-u4-X08"},{"t":"「다른 의견을 낸 친구를 빼고 정하자.」","mis":"K5-2-u4-X26"}],"explanation":["다르니까 토의해요.","목소리로 정하지 않아요.","다른 의견은 견주어 볼 재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#4','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C7',3,'mc','auto','「고학년이 먼저 쓰자」 의견을 「여러 사람에게 도움이 되는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X07','K5-2-u4-X10']::text[],false,'{"seq":4,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"「고학년이 먼저 쓰자」 의견을 「여러 사람에게 도움이 되는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"저학년은 비 오는 날 체육관을 쓰기 어려워 모든 학년에 도움이 되지는 않는다","correct":true},{"t":"고학년이 말했으니 가장 좋은 의견이다","mis":"K5-2-u4-X08"},{"t":"기준으로 따질 필요 없이 바로 정하면 된다","mis":"K5-2-u4-X07"},{"t":"단점이 하나도 없는 의견이다","mis":"K5-2-u4-X10"}],"explanation":["말한 사람이 기준이 아니에요.","기준으로 따져요.","누구에게 도움이 되는지 살펴요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#5','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C3',3,'error','auto','토의를 마친 뒤 친구들이 나눈 말이에요. 의견 조정을 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X12','K5-2-u4-X11']::text[],false,'{"seq":5,"concept":"K5-2-u4-C3","difficulty":3,"kind":"error","stem":"토의를 마친 뒤 친구들이 나눈 말이에요. 의견 조정을 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「내 의견이 조금 바뀌었으니 내가 진 거야.」","correct":true,"mis_target":"K5-2-u4-X03"},{"t":"「두 의견의 좋은 점을 모아서 더 나아졌어.」","mis":"K5-2-u4-X12"},{"t":"「서로 조금씩 양보하니 모두 받아들일 수 있었어.」","mis":"K5-2-u4-X11"}],"explanation":["알맞게 이해했어요.","알맞게 이해했어요.","바뀐 것은 진 것이 아니라 나아진 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#6','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C2',3,'mc','auto','토의에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X38','K5-2-u4-X08']::text[],false,'{"seq":6,"concept":"K5-2-u4-C2","difficulty":3,"kind":"mc","stem":"토의에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여럿이 함께 더 나은 방법을 찾는 자리이다","correct":true},{"t":"누가 말을 잘하는지 겨루는 자리이다","mis":"K5-2-u4-X02"},{"t":"선생님이 정답을 알려 주는 자리이다","mis":"K5-2-u4-X38"},{"t":"먼저 말한 사람의 의견을 따르는 자리이다","mis":"K5-2-u4-X08"}],"explanation":["겨루지 않아요.","정해진 정답은 없어요.","함께 찾는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#7','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C4',3,'mc','auto','의견을 말할 때 까닭이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X04','K5-2-u4-X26']::text[],false,'{"seq":7,"concept":"K5-2-u4-C4","difficulty":3,"kind":"mc","stem":"의견을 말할 때 까닭이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"까닭이 있어야 다른 의견과 견주어 따져 볼 수 있어서","correct":true},{"t":"까닭이 길수록 뽑히기 쉬워서","mis":"K5-2-u4-X04"},{"t":"까닭을 말하면 다른 친구가 말을 못 해서","mis":"K5-2-u4-X26"},{"t":"까닭은 선생님만 들으면 되어서","mis":"K5-2-u4-X04"}],"explanation":["길이가 중요하지 않아요.","모두가 말해야 해요.","견주려면 까닭이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#8','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C1',4,'essay','teacher','두 대표의 의견을 각각 쓰고, 두 의견의 좋은 점을 살린 내 의견을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C1","difficulty":4,"kind":"essay","stem":"두 대표의 의견을 각각 쓰고, 두 의견의 좋은 점을 살린 내 의견을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 고학년 대표는 고학년이 먼저 쓰자고 했고, 저학년 대표는 요일을 학년별로 정하자고 했다. 나는 요일을 학년별로 나누되, 고학년이 쓰는 날에는 저학년 몇 반도 함께 쓰며 고학년이 질서를 도와주자고 하겠다. 모든 학년이 고르게 쓰면서 질서도 지킬 수 있기 때문이다.","scoring_points":["두 의견을 바르게 썼는가","두 의견의 좋은 점을 살렸는가","내 의견에 까닭이 있는가"]},"explanation":["두 의견을 찾아요.","좋은 점을 살려요.","까닭을 덧붙여요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#9','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C3',4,'essay','teacher','의견을 조정해 정하는 것과 처음부터 손을 들어 많은 쪽으로 정하는 것을 견주어, 의견을 조정하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C3","difficulty":4,"kind":"essay","stem":"의견을 조정해 정하는 것과 처음부터 손을 들어 많은 쪽으로 정하는 것을 견주어, 의견을 조정하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 손을 들어 바로 정하면 빠르지만 적은 쪽 친구들의 생각은 반영되지 않는다. 의견을 조정하면 시간이 걸려도 여러 의견의 좋은 점을 살려 더 많은 친구가 받아들이고 함께 실천할 수 있다.","scoring_points":["손을 들어 정하는 방법의 특징을 썼는가","의견 조정의 특징을 썼는가","의견 조정의 좋은 점을 썼는가"]},"explanation":["빠르지만 아쉬움이 있어요.","함께 고쳐 가요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#10','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C5',4,'essay','teacher','의견이 맞지 않아 정하기 어려웠던 경험을 하나 쓰고, 그때 어떤 말이나 행동이 있었으면 좋았을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C5","difficulty":4,"kind":"essay","stem":"의견이 맞지 않아 정하기 어려웠던 경험을 하나 쓰고, 그때 어떤 말이나 행동이 있었으면 좋았을지 쓰세요.","answer_guide":{"answer":"예: 모둠 발표 주제를 정할 때 두 친구가 서로 자기 주제만 하자고 해서 시간이 다 지나 버렸다. 그때 누가 맞는지 따지기보다 「두 주제의 좋은 점을 먼저 말해 보자.」라고 했다면 함께 정할 수 있었을 것 같다.","scoring_points":["경험을 구체적으로 썼는가","필요했던 말이나 행동을 썼는가","탓하기가 아니라 방법을 찾았는가"]},"explanation":["경험을 떠올려요.","필요한 말을 찾아요.","탓하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#1','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C6',1,'mc','auto','토의를 통해 풀려는 문제는 무엇인가요?',ARRAY['K5-2-u4-X06']::text[],false,'{"seq":1,"concept":"K5-2-u4-C6","difficulty":1,"kind":"mc","stem":"토의를 통해 풀려는 문제는 무엇인가요?","options":[{"t":"복도에서 뛰다가 부딪치는 문제","correct":true},{"t":"급식이 남는 문제","mis":"K5-2-u4-X06"},{"t":"교실이 더러운 문제","mis":"K5-2-u4-X06"},{"t":"포스터가 찢어지는 문제","mis":"K5-2-u4-X06"}],"explanation":["토의에 없는 문제예요.","토의에 없는 문제예요.","사회자가 처음에 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간마다 복도에서 뛰다가 부딪치는 일이 잦습니다. 복도를 안전하게 쓰는 방법을 토의해 봅시다."},{"who":"도윤","text":"복도 지킴이를 정하면 좋겠습니다. 뛰는 친구에게 바로 「걸어 주세요.」라고 알려 줄 수 있기 때문입니다."},{"who":"서아","text":"복도 안전 포스터를 만들어 붙이면 어떨까요? 오가며 볼 때마다 조심하게 될 것입니다."},{"who":"지후","text":"복도에서 뛴 사람은 다음 쉬는 시간에 교실에만 있기로 하면 좋겠습니다. 그러면 금방 줄어들 것입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#2','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C7',1,'mc','auto','의견을 조정할 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X07']::text[],false,'{"seq":2,"concept":"K5-2-u4-C7","difficulty":1,"kind":"mc","stem":"의견을 조정할 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"의견을 검토할 기준 마련하기","correct":true},{"t":"합의점 찾기","mis":"K5-2-u4-X13"},{"t":"실천할 의견 정하기","mis":"K5-2-u4-X13"},{"t":"마음에 드는 의견 고르기","mis":"K5-2-u4-X07"}],"explanation":["마지막 차례예요.","조정을 마친 뒤예요.","기준이 있어야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#3','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C11',1,'mc','auto','서로 조금씩 양보해 의견이 하나로 모이는 자리를 무엇이라고 하나요?',ARRAY['K5-2-u4-X11','K5-2-u4-X10','K5-2-u4-X07']::text[],false,'{"seq":3,"concept":"K5-2-u4-C11","difficulty":1,"kind":"mc","stem":"서로 조금씩 양보해 의견이 하나로 모이는 자리를 무엇이라고 하나요?","options":[{"t":"합의점","correct":true},{"t":"출발점","mis":"K5-2-u4-X11"},{"t":"단점","mis":"K5-2-u4-X10"},{"t":"기준","mis":"K5-2-u4-X07"}],"explanation":["처음 자리예요.","아쉬운 점이에요.","의견이 모이는 자리가 합의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#4','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C10',1,'ox','auto','토의에서 친구 의견의 단점을 말하는 것은 친구를 비난하는 일이에요.',ARRAY['K5-2-u4-X11']::text[],false,'{"seq":4,"concept":"K5-2-u4-C10","difficulty":1,"kind":"ox","stem":"토의에서 친구 의견의 단점을 말하는 것은 친구를 비난하는 일이에요.","answer":"X","reason_options":[{"t":"단점을 따져야 더 나은 의견을 찾을 수 있기 때문에","correct":true},{"t":"단점을 들으면 친구가 속상하기 때문에","mis":"K5-2-u4-X11"}],"mis":"K5-2-u4-X11","explanation":["단점 말하기는 필요한 과정이에요.","의견을 두고 말해요.","최선의 의견을 찾기 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#5','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C6',2,'mc','auto','서아가 제안한 의견은 무엇인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X16']::text[],false,'{"seq":5,"concept":"K5-2-u4-C6","difficulty":2,"kind":"mc","stem":"서아가 제안한 의견은 무엇인가요?","options":[{"t":"복도 안전 포스터를 만들어 붙이자","correct":true},{"t":"복도 지킴이를 정하자","mis":"K5-2-u4-X06"},{"t":"뛴 사람은 교실에만 있자","mis":"K5-2-u4-X06"},{"t":"복도를 넓히자","mis":"K5-2-u4-X16"}],"explanation":["도윤이의 의견이에요.","지후의 의견이에요.","서아는 포스터를 제안했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간마다 복도에서 뛰다가 부딪치는 일이 잦습니다. 복도를 안전하게 쓰는 방법을 토의해 봅시다."},{"who":"도윤","text":"복도 지킴이를 정하면 좋겠습니다. 뛰는 친구에게 바로 「걸어 주세요.」라고 알려 줄 수 있기 때문입니다."},{"who":"서아","text":"복도 안전 포스터를 만들어 붙이면 어떨까요? 오가며 볼 때마다 조심하게 될 것입니다."},{"who":"지후","text":"복도에서 뛴 사람은 다음 쉬는 시간에 교실에만 있기로 하면 좋겠습니다. 그러면 금방 줄어들 것입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#6','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C9',2,'mc','auto','「교실에 남기」 의견의 단점으로 표에 나온 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X09']::text[],false,'{"seq":6,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"「교실에 남기」 의견의 단점으로 표에 나온 것은 어느 것인가요?","options":[{"t":"쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","correct":true},{"t":"뛰는 일이 빨리 줄 수 있다","mis":"K5-2-u4-X10"},{"t":"우리가 쉽게 만들 수 있다","mis":"K5-2-u4-X09"},{"t":"단점은 하나도 없다","mis":"K5-2-u4-X10"}],"explanation":["장점이에요.","포스터의 장점이에요.","표의 단점 칸을 봐요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#7','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C9',2,'match','auto','의견을 조정하는 차례와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C9","difficulty":2,"kind":"match","stem":"의견을 조정하는 차례와 하는 일을 알맞게 이으세요.","pairs":[{"l":"기준 마련","r":"무엇으로 견줄지 함께 정하기"},{"l":"장단점 검토","r":"기준에 비추어 좋은 점과 아쉬운 점 따지기"},{"l":"합의점 찾기","r":"장점을 살려 모두가 동의할 의견 만들기"}],"mis":"K5-2-u4-X13","explanation":["먼저 기준을 정해요.","기준으로 따져요.","장점을 살려 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#8','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C10',2,'error','auto','단점을 말하는 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X09','K5-2-u4-X10']::text[],false,'{"seq":8,"concept":"K5-2-u4-C10","difficulty":2,"kind":"error","stem":"단점을 말하는 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「지후는 늘 엉뚱한 말만 하니까 이번 의견도 별로야.」","correct":true,"mis_target":"K5-2-u4-X11"},{"t":"「지킴이를 몇 명만 맡으면 힘들 것 같아.」","mis":"K5-2-u4-X09"},{"t":"「포스터는 시간이 지나면 눈에 덜 띌 것 같아.」","mis":"K5-2-u4-X10"}],"explanation":["의견을 두고 말했어요.","의견을 두고 말했어요.","사람이 아니라 의견을 두고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#9','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C12',2,'mc','auto','표의 합의점은 어떻게 만든 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X08','K5-2-u4-X03']::text[],false,'{"seq":9,"concept":"K5-2-u4-C12","difficulty":2,"kind":"mc","stem":"표의 합의점은 어떻게 만든 것인가요?","options":[{"t":"두 의견의 장점을 합쳤다","correct":true},{"t":"한 의견만 그대로 골랐다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 의견을 따랐다","mis":"K5-2-u4-X08"},{"t":"세 의견을 모두 버렸다","mis":"K5-2-u4-X03"}],"explanation":["그대로 고르지 않았어요.","목소리로 정하지 않았어요.","지킴이와 포스터를 합쳤어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#10','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C13',3,'mc','auto','장단점을 따지다 보니 기준이 부족하다는 것을 알았을 때 가장 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X01','K5-2-u4-X08']::text[],false,'{"seq":10,"concept":"K5-2-u4-C13","difficulty":3,"kind":"mc","stem":"장단점을 따지다 보니 기준이 부족하다는 것을 알았을 때 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"기준 마련하기로 되돌아가 기준을 더한다","correct":true},{"t":"차례를 거꾸로 갈 수 없으니 그대로 정한다","mis":"K5-2-u4-X13"},{"t":"토의를 그만둔다","mis":"K5-2-u4-X01"},{"t":"가장 먼저 나온 의견으로 정한다","mis":"K5-2-u4-X08"}],"explanation":["되돌아갈 수 있어요.","그만두지 않아요.","필요하면 앞 차례로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#1','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C13',2,'ox','auto','의견을 조정하는 차례는 한 방향으로만 가야 해서 앞 차례로 되돌아갈 수 없어요.',ARRAY['K5-2-u4-X13']::text[],false,'{"seq":1,"concept":"K5-2-u4-C13","difficulty":2,"kind":"ox","stem":"의견을 조정하는 차례는 한 방향으로만 가야 해서 앞 차례로 되돌아갈 수 없어요.","answer":"X","reason_options":[{"t":"필요하면 앞 차례로 되돌아가 다시 따져 볼 수 있기 때문에","correct":true},{"t":"차례를 바꾸면 토의가 틀리기 때문에","mis":"K5-2-u4-X13"}],"mis":"K5-2-u4-X13","explanation":["고정된 길이 아니에요.","오가며 조정해요.","되돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#2','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C8',2,'mc','auto','복도 문제를 토의할 때 더할 수 있는 검토 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X09','K5-2-u4-X16']::text[],false,'{"seq":2,"concept":"K5-2-u4-C8","difficulty":2,"kind":"mc","stem":"복도 문제를 토의할 때 더할 수 있는 검토 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"돈이 많이 들지 않는가?","correct":true},{"t":"누가 먼저 말했는가?","mis":"K5-2-u4-X08"},{"t":"글자 수가 적은가?","mis":"K5-2-u4-X09"},{"t":"가장 재미있게 들리는가?","mis":"K5-2-u4-X16"}],"explanation":["차례는 기준이 아니에요.","글자 수는 관계없어요.","비용도 기준이 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#3','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C14',3,'mc','auto','끝내 합의점을 찾지 못해 손을 들어 많은 쪽으로 정했을 때의 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X14','K5-2-u4-X01']::text[],false,'{"seq":3,"concept":"K5-2-u4-C14","difficulty":3,"kind":"mc","stem":"끝내 합의점을 찾지 못해 손을 들어 많은 쪽으로 정했을 때의 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 전에 장단점을 따진 덕분에 모두가 의견을 잘 알고 정할 수 있었다","correct":true},{"t":"토의는 헛수고였다","mis":"K5-2-u4-X14"},{"t":"처음부터 손을 들어 정했으면 됐다","mis":"K5-2-u4-X14"},{"t":"적은 쪽 친구들의 생각은 틀린 것이다","mis":"K5-2-u4-X01"}],"explanation":["헛수고가 아니에요.","목적은 합의점이에요.","따져 본 과정이 쓸모 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#4','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C10',3,'mc','auto','단점을 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X10']::text[],false,'{"seq":4,"concept":"K5-2-u4-C10","difficulty":3,"kind":"mc","stem":"단점을 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「포스터는 쉽게 만들 수 있지만, 오래 지나면 눈에 덜 띌 것 같아.」","correct":true},{"t":"「포스터 같은 건 아무도 안 봐.」","mis":"K5-2-u4-X11"},{"t":"「서아 의견은 늘 별로야.」","mis":"K5-2-u4-X11"},{"t":"「단점은 말하지 않을게.」","mis":"K5-2-u4-X10"}],"explanation":["함부로 깎아내리는 말이에요.","사람을 두고 한 말이에요.","장점도 인정하고 의견을 두고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#5','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C12',3,'error','auto','합의점에 대한 친구들의 말이에요. 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X11','K5-2-u4-X19']::text[],false,'{"seq":5,"concept":"K5-2-u4-C12","difficulty":3,"kind":"error","stem":"합의점에 대한 친구들의 말이에요. 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「합의점은 세 의견 가운데 하나를 고르는 것뿐이야.」","correct":true,"mis_target":"K5-2-u4-X12"},{"t":"「두 의견을 합쳐 새 의견을 만들 수도 있어.」","mis":"K5-2-u4-X11"},{"t":"「두 가지 의견을 함께 고를 수도 있어.」","mis":"K5-2-u4-X19"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","합의점은 여러 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#6','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C7',3,'mc','auto','「지킴이」 의견을 「실천할 수 있는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X04','K5-2-u4-X08','K5-2-u4-X11']::text[],false,'{"seq":6,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"「지킴이」 의견을 「실천할 수 있는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"몇 명만 늘 맡으면 힘들어 오래 실천하기 어려울 수 있다","correct":true},{"t":"지킴이라는 이름이 멋져서 실천하기 쉽다","mis":"K5-2-u4-X04"},{"t":"도윤이가 말했으니 실천할 수 있다","mis":"K5-2-u4-X08"},{"t":"기준으로 따지면 친구가 속상하다","mis":"K5-2-u4-X11"}],"explanation":["이름은 까닭이 아니에요.","말한 사람이 기준이 아니에요.","실천할 수 있는지 따져요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#7','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C11',3,'mc','auto','지킴이 의견이 「모두 돌아가며 맡기」로 바뀌어 합의점에 들어갔어요. 이를 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X20','K5-2-u4-X38']::text[],false,'{"seq":7,"concept":"K5-2-u4-C11","difficulty":3,"kind":"mc","stem":"지킴이 의견이 「모두 돌아가며 맡기」로 바뀌어 합의점에 들어갔어요. 이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지킴이 의견의 단점이 보완되어 더 좋아졌다","correct":true},{"t":"도윤이의 의견은 사라졌다","mis":"K5-2-u4-X03"},{"t":"도윤이가 토의에서 졌다","mis":"K5-2-u4-X20"},{"t":"지킴이 의견은 처음부터 정답이었다","mis":"K5-2-u4-X38"}],"explanation":["의견은 남아 있어요.","진 것이 아니에요.","단점을 보완해 나아졌어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#8','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C9',4,'essay','teacher','지후의 의견을 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C9","difficulty":4,"kind":"essay","stem":"지후의 의견을 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.","answer_guide":{"answer":"예: 효과적인가 기준으로 보면 뛰는 일이 빨리 줄 수 있다는 장점이 있다. 여러 사람에게 도움이 되는가 기준으로 보면 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다는 단점이 있다.","scoring_points":["기준 두 가지를 밝혔는가","기준에 비추어 장점을 썼는가","기준에 비추어 단점을 썼는가"]},"explanation":["기준을 골라요.","장점을 써요.","단점도 의견을 두고 써요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간마다 복도에서 뛰다가 부딪치는 일이 잦습니다. 복도를 안전하게 쓰는 방법을 토의해 봅시다."},{"who":"도윤","text":"복도 지킴이를 정하면 좋겠습니다. 뛰는 친구에게 바로 「걸어 주세요.」라고 알려 줄 수 있기 때문입니다."},{"who":"서아","text":"복도 안전 포스터를 만들어 붙이면 어떨까요? 오가며 볼 때마다 조심하게 될 것입니다."},{"who":"지후","text":"복도에서 뛴 사람은 다음 쉬는 시간에 교실에만 있기로 하면 좋겠습니다. 그러면 금방 줄어들 것입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#9','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C11',4,'essay','teacher','세 의견의 장점을 살려 모두가 동의할 만한 합의점을 새로 만들어 쓰고, 어떤 의견의 장점을 살렸는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C11","difficulty":4,"kind":"essay","stem":"세 의견의 장점을 살려 모두가 동의할 만한 합의점을 새로 만들어 쓰고, 어떤 의견의 장점을 살렸는지 쓰세요.","answer_guide":{"answer":"예: 지킴이를 모두 돌아가며 맡고, 복도 모퉁이에 포스터를 붙이고, 일주일 동안 잘 걸은 날이 많으면 학급 칭찬 붙임딱지를 받는다. 지킴이의 바로 알려 주는 점과 포스터의 쉽게 만드는 점, 교실에 남기의 빨리 줄어드는 점을 벌 대신 칭찬으로 바꾸어 살렸다.","scoring_points":["합의점을 썼는가","살린 장점을 밝혔는가","여럿이 동의할 만한가"]},"explanation":["새 합의점을 써요.","살린 장점을 밝혀요.","모두가 받아들일 만한지 봐요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#10','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C13',4,'essay','teacher','의견을 조정하는 세 차례를 쓰고, 조정이 막힐 때 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C13","difficulty":4,"kind":"essay","stem":"의견을 조정하는 세 차례를 쓰고, 조정이 막힐 때 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 의견을 검토할 기준 마련하기, 의견의 장점과 단점 검토하기, 합의점 찾기 차례로 한다. 합의점이 보이지 않으면 앞 차례로 되돌아가 기준을 더하거나 장단점을 다시 따져 본다.","scoring_points":["세 차례를 바르게 썼는가","차례를 알맞게 놓았는가","막힐 때 되돌아갈 수 있음을 썼는가"]},"explanation":["세 차례예요.","기준이 먼저예요.","되돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#1','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C15',1,'mc','auto','토의 주제로 정하기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15']::text[],false,'{"seq":1,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"토의 주제로 정하기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 신발장을 깔끔하게 쓸까?","correct":true},{"t":"신발장이 엉망이라 정말 싫다.","mis":"K5-2-u4-X15"},{"t":"신발장은 누가 어질렀어?","mis":"K5-2-u4-X15"},{"t":"신발장 정리는 내 일이 아니다.","mis":"K5-2-u4-X15"}],"explanation":["불평하는 말이에요.","탓하는 물음이에요.","함께 방법을 찾는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#2','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C16',1,'mc','auto','토의 주제를 고를 때 생각할 것이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u4-X16']::text[],false,'{"seq":2,"concept":"K5-2-u4-C16","difficulty":1,"kind":"mc","stem":"토의 주제를 고를 때 생각할 것이 아닌 것은 어느 것인가요?","options":[{"t":"가장 재미있게 들리는 문제인가?","correct":true},{"t":"우리와 관련이 있는 문제인가?","mis":"K5-2-u4-X16"},{"t":"우리가 직접 풀 수 있는 문제인가?","mis":"K5-2-u4-X16"},{"t":"가장 먼저 풀어야 할 문제인가?","mis":"K5-2-u4-X16"}],"explanation":["생각할 것이에요.","생각할 것이에요.","재미만으로 고르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#3','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C17',1,'mc','auto','친구 의견을 듣고 궁금한 점을 묻는 것은 무엇을 하는 일인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X17','K5-2-u4-X18']::text[],false,'{"seq":3,"concept":"K5-2-u4-C17","difficulty":1,"kind":"mc","stem":"친구 의견을 듣고 궁금한 점을 묻는 것은 무엇을 하는 일인가요?","options":[{"t":"질문하며 듣기","correct":true},{"t":"맞장구만 치기","mis":"K5-2-u4-X21"},{"t":"못 들은 척하기","mis":"K5-2-u4-X17"},{"t":"끼어들어 말 끊기","mis":"K5-2-u4-X18"}],"explanation":["묻지 않는 일이에요.","듣지 않는 일이에요.","물으며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#4','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C20',1,'ox','auto','내 의견이 모둠 의견으로 뽑히지 않으면 토의에서 진 거예요.',ARRAY['K5-2-u4-X20']::text[],false,'{"seq":4,"concept":"K5-2-u4-C20","difficulty":1,"kind":"ox","stem":"내 의견이 모둠 의견으로 뽑히지 않으면 토의에서 진 거예요.","answer":"X","reason_options":[{"t":"함께 말하고 고친 과정 속에 내 생각도 들어 있기 때문에","correct":true},{"t":"토의는 의견이 뽑힌 사람이 이기는 자리이기 때문에","mis":"K5-2-u4-X20"}],"mis":"K5-2-u4-X20","explanation":["토의에는 이기고 짐이 없어요.","내 생각도 들어 있어요.","참여한 것이 소중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#5','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C15',2,'mc','auto','상황 ㉯를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X15']::text[],false,'{"seq":5,"concept":"K5-2-u4-C15","difficulty":2,"kind":"mc","stem":"상황 ㉯를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 실내화를 제자리에 꽂을까?","correct":true},{"t":"어떻게 하면 남는 우유를 줄일까?","mis":"K5-2-u4-X06"},{"t":"어떻게 하면 가위를 잘 챙길까?","mis":"K5-2-u4-X06"},{"t":"실내화를 어지른 사람은 누구일까?","mis":"K5-2-u4-X15"}],"explanation":["㉮의 주제예요.","㉰의 주제예요.","㉯는 신발장 문제예요."],"asset":{"type":"passage","lines":["㉮ 마시지 않은 우유가 많이 남아요.","㉯ 신발장에 실내화가 뒤죽박죽 꽂혀 있어요.","㉰ 모둠 바구니의 가위와 풀이 자꾸 없어져요."],"title":"학교에서 찾은 세 가지 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#6','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C17',2,'mc','auto','유나의 첫 번째 말은 어떤 일을 했나요?',ARRAY['K5-2-u4-X18','K5-2-u4-X21','K5-2-u4-X15']::text[],false,'{"seq":6,"concept":"K5-2-u4-C17","difficulty":2,"kind":"mc","stem":"유나의 첫 번째 말은 어떤 일을 했나요?","options":[{"t":"궁금한 점을 물어 이름표 의견의 빈틈을 채웠다","correct":true},{"t":"민재의 의견을 놀렸다","mis":"K5-2-u4-X18"},{"t":"민재의 의견에 맞장구만 쳤다","mis":"K5-2-u4-X21"},{"t":"토의 주제를 바꾸었다","mis":"K5-2-u4-X15"}],"explanation":["공손하게 물었어요.","맞장구가 아니에요.","질문으로 빈틈을 채웠어요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#7','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C16',2,'match','auto','주제를 고르는 기준과 알맞은 물음을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C16","difficulty":2,"kind":"match","stem":"주제를 고르는 기준과 알맞은 물음을 이으세요.","pairs":[{"l":"관련","r":"우리 반 친구들과 상관있는 일인가?"},{"l":"실천","r":"우리 손으로 직접 바꿀 수 있는가?"},{"l":"시급","r":"가장 먼저 풀어야 할 일인가?"}],"mis":"K5-2-u4-X16","explanation":["우리와 관련이 있어요.","직접 풀 수 있어요.","먼저 풀어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#8','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C18',2,'error','auto','현우의 의견에 한 질문들이에요. 알맞지 않은 질문은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":8,"concept":"K5-2-u4-C18","difficulty":2,"kind":"error","stem":"현우의 의견에 한 질문들이에요. 알맞지 않은 질문은 어느 것인가요?","options":[{"t":"「너는 왜 맨날 그런 말만 해?」","correct":true,"mis_target":"K5-2-u4-X18"},{"t":"「당번은 몇 명이 얼마 동안 맡아?」","mis":"K5-2-u4-X17"},{"t":"「궁금해서 묻는데, 당번이 없는 날은 어떻게 해?」","mis":"K5-2-u4-X17"}],"explanation":["알맞은 질문이에요.","알맞은 질문이에요.","공격하는 말은 질문이 아니에요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#9','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C19',2,'mc','auto','모둠이 의견을 하나로 고칠 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u4-X19','K5-2-u4-X21','K5-2-u4-X10']::text[],false,'{"seq":9,"concept":"K5-2-u4-C19","difficulty":2,"kind":"mc","stem":"모둠이 의견을 하나로 고칠 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"여러 의견의 장점을 살려 하나로 고친다","correct":true},{"t":"먼저 나온 의견 하나만 남긴다","mis":"K5-2-u4-X19"},{"t":"모두 좋다고 하고 바로 끝낸다","mis":"K5-2-u4-X21"},{"t":"단점이 있는 의견은 다 버린다","mis":"K5-2-u4-X10"}],"explanation":["장점을 버리게 돼요.","따지지 않았어요.","장점을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#10','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C21',3,'mc','auto','모둠원 모두가 「좋아, 좋아.」라고만 해서 금세 정했는데 실천해 보니 문제가 많았어요. 무엇이 빠졌을까요?',ARRAY['K5-2-u4-X14','K5-2-u4-X08','K5-2-u4-X15']::text[],false,'{"seq":10,"concept":"K5-2-u4-C21","difficulty":3,"kind":"mc","stem":"모둠원 모두가 「좋아, 좋아.」라고만 해서 금세 정했는데 실천해 보니 문제가 많았어요. 무엇이 빠졌을까요?","options":[{"t":"단점을 따지고 질문하는 과정","correct":true},{"t":"손을 드는 과정","mis":"K5-2-u4-X14"},{"t":"목소리를 키우는 과정","mis":"K5-2-u4-X08"},{"t":"주제를 바꾸는 과정","mis":"K5-2-u4-X15"}],"explanation":["손을 들어도 마찬가지예요.","목소리는 관계없어요.","따지고 물어야 문제가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#1','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C16',2,'mc','auto','세 문제 가운데 하나를 고를 때 「가장 먼저 풀어야 할 문제인가」를 따지는 까닭은 무엇인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31','K5-2-u4-X26']::text[],false,'{"seq":1,"concept":"K5-2-u4-C16","difficulty":2,"kind":"mc","stem":"세 문제 가운데 하나를 고를 때 「가장 먼저 풀어야 할 문제인가」를 따지는 까닭은 무엇인가요?","options":[{"t":"시간이 한정되어 있어 급한 문제부터 함께 풀려고","correct":true},{"t":"가장 재미있는 문제를 고르려고","mis":"K5-2-u4-X16"},{"t":"어른들만 풀 수 있는 문제를 고르려고","mis":"K5-2-u4-X31"},{"t":"친구 한 명이 좋아하는 문제를 고르려고","mis":"K5-2-u4-X26"}],"explanation":["재미가 기준이 아니에요.","우리가 풀 문제를 골라요.","급한 문제부터 풀어요."],"asset":{"type":"passage","lines":["㉮ 마시지 않은 우유가 많이 남아요.","㉯ 신발장에 실내화가 뒤죽박죽 꽂혀 있어요.","㉰ 모둠 바구니의 가위와 풀이 자꾸 없어져요."],"title":"학교에서 찾은 세 가지 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#2','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C18',2,'ox','auto','질문은 친구 의견의 빈틈을 공격하려고 하는 말이에요.',ARRAY['K5-2-u4-X18']::text[],false,'{"seq":2,"concept":"K5-2-u4-C18","difficulty":2,"kind":"ox","stem":"질문은 친구 의견의 빈틈을 공격하려고 하는 말이에요.","answer":"X","reason_options":[{"t":"궁금한 점을 물어 의견을 더 또렷하게 다듬으려는 말이기 때문에","correct":true},{"t":"질문을 많이 할수록 친구 의견을 이길 수 있기 때문에","mis":"K5-2-u4-X18"}],"mis":"K5-2-u4-X18","explanation":["이기려는 말이 아니에요.","함께 다듬어요.","궁금해서 묻는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#3','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C17',3,'mc','auto','유나의 질문 덕분에 이름표 의견은 어떻게 바뀌었나요?',ARRAY['K5-2-u4-X03','K5-2-u4-X17','K5-2-u4-X20']::text[],false,'{"seq":3,"concept":"K5-2-u4-C17","difficulty":3,"kind":"mc","stem":"유나의 질문 덕분에 이름표 의견은 어떻게 바뀌었나요?","options":[{"t":"투명 테이프로 덮어 오래가게 하는 의견으로 보완되었다","correct":true},{"t":"이름표 의견이 버려졌다","mis":"K5-2-u4-X03"},{"t":"질문 때문에 토의가 멈추었다","mis":"K5-2-u4-X17"},{"t":"민재가 의견을 거두고 토의에서 졌다","mis":"K5-2-u4-X20"}],"explanation":["버려지지 않았어요.","토의가 더 나아졌어요.","질문이 빈틈을 채웠어요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#4','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C20',3,'mc','auto','내 의견이 뽑히지 않아 속상한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X20','K5-2-u4-X08','K5-2-u4-X38']::text[],false,'{"seq":4,"concept":"K5-2-u4-C20","difficulty":3,"kind":"mc","stem":"내 의견이 뽑히지 않아 속상한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「네 질문 덕분에 모둠 의견이 더 좋아졌어. 그 안에 네 생각도 있어.」","correct":true},{"t":"「뽑히지 않았으니 다음엔 말하지 마.」","mis":"K5-2-u4-X20"},{"t":"「목소리를 더 크게 했어야지.」","mis":"K5-2-u4-X08"},{"t":"「네 의견은 원래 틀렸어.」","mis":"K5-2-u4-X38"}],"explanation":["말하는 것이 소중해요.","목소리로 정하지 않아요.","참여한 가치를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#5','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C19',3,'error','auto','모둠 의견을 고치는 과정이에요. 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X19','K5-2-u4-X12']::text[],false,'{"seq":5,"concept":"K5-2-u4-C19","difficulty":3,"kind":"error","stem":"모둠 의견을 고치는 과정이에요. 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「단점이 하나라도 있는 의견은 모두 지우자.」","correct":true,"mis_target":"K5-2-u4-X10"},{"t":"「이름표 의견의 장점을 남기고 테이프로 보완하자.」","mis":"K5-2-u4-X19"},{"t":"「당번은 모두 돌아가며 맡게 하자.」","mis":"K5-2-u4-X12"}],"explanation":["알맞은 과정이에요.","알맞은 과정이에요.","단점은 보완할 거리예요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#6','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C15',3,'mc','auto','「급식실 줄이 너무 길어서 짜증 나.」를 토의 주제로 바꾼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31','K5-2-u4-X16']::text[],false,'{"seq":6,"concept":"K5-2-u4-C15","difficulty":3,"kind":"mc","stem":"「급식실 줄이 너무 길어서 짜증 나.」를 토의 주제로 바꾼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 급식실 줄을 짧게 할까?","correct":true},{"t":"급식실 줄은 누구 때문에 길까?","mis":"K5-2-u4-X15"},{"t":"급식실 줄은 원래 길다.","mis":"K5-2-u4-X31"},{"t":"급식실에 가지 말자.","mis":"K5-2-u4-X16"}],"explanation":["탓하는 물음이에요.","포기하는 말이에요.","방법을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#7','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C21',3,'mc','auto','단점을 말하고 질문하는 것이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X21','K5-2-u4-X20']::text[],false,'{"seq":7,"concept":"K5-2-u4-C21","difficulty":3,"kind":"mc","stem":"단점을 말하고 질문하는 것이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실천하기 전에 생길 문제를 미리 찾아 의견을 보완할 수 있어서","correct":true},{"t":"친구 의견을 빨리 떨어뜨릴 수 있어서","mis":"K5-2-u4-X11"},{"t":"토의를 길게 끌 수 있어서","mis":"K5-2-u4-X21"},{"t":"내 의견만 뽑히게 할 수 있어서","mis":"K5-2-u4-X20"}],"explanation":["떨어뜨리려는 게 아니에요.","길게 끌려는 게 아니에요.","미리 찾아 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#8','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C15',4,'essay','teacher','세 문제 가운데 하나를 골라 토의 주제를 「어떻게 하면 ~할까?」 꼴로 쓰고, 주제를 고르는 기준 두 가지에 비추어 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C15","difficulty":4,"kind":"essay","stem":"세 문제 가운데 하나를 골라 토의 주제를 「어떻게 하면 ~할까?」 꼴로 쓰고, 주제를 고르는 기준 두 가지에 비추어 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 어떻게 하면 모둠 바구니의 가위와 풀을 잘 챙길까? 우리 모둠이 날마다 쓰는 물건이라 우리와 관련이 있고, 정리 방법을 정하면 우리가 직접 바꿀 수 있기 때문이다.","scoring_points":["주제를 방법을 묻는 꼴로 썼는가","기준 두 가지를 밝혔는가","기준에 비추어 까닭을 썼는가"]},"explanation":["물음으로 써요.","기준을 밝혀요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 마시지 않은 우유가 많이 남아요.","㉯ 신발장에 실내화가 뒤죽박죽 꽂혀 있어요.","㉰ 모둠 바구니의 가위와 풀이 자꾸 없어져요."],"title":"학교에서 찾은 세 가지 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#9','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C17',4,'essay','teacher','현우의 「정리 당번」 의견에 궁금한 점을 묻는 공손한 질문을 두 개 쓰고, 그 질문이 의견을 어떻게 다듬을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C17","difficulty":4,"kind":"essay","stem":"현우의 「정리 당번」 의견에 궁금한 점을 묻는 공손한 질문을 두 개 쓰고, 그 질문이 의견을 어떻게 다듬을지 쓰세요.","answer_guide":{"answer":"예: 「궁금해서 묻는데, 당번은 며칠씩 돌아가며 맡아?」 「당번이 학교에 오지 못한 날은 누가 대신해?」처럼 묻겠다. 이 질문에 답하다 보면 당번을 정하는 방법과 빈자리를 채우는 방법까지 정해져 의견이 더 단단해진다.","scoring_points":["질문을 두 개 썼는가","질문이 공손한가","질문이 의견을 다듬는 점을 썼는가"]},"explanation":["두 개를 써요.","공손하게 물어요.","다듬어지는 점을 써요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#10','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C19',4,'essay','teacher','민재 · 유나 · 현우의 의견에서 장점을 살려 하나의 모둠 의견으로 고쳐 쓰고, 그렇게 고친 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C19","difficulty":4,"kind":"essay","stem":"민재 · 유나 · 현우의 의견에서 장점을 살려 하나의 모둠 의견으로 고쳐 쓰고, 그렇게 고친 까닭을 쓰세요.","answer_guide":{"answer":"예: 칸마다 이름표를 붙이고 투명 테이프로 덮으며, 정리 당번은 모두 돌아가며 아침마다 살핀다. 이름표가 오래가고 자기 칸이 바로 보이며, 한 사람만 애쓰지 않아도 되기 때문이다.","scoring_points":["세 의견의 장점을 살렸는가","하나의 의견으로 고쳤는가","고친 까닭을 썼는가"]},"explanation":["장점을 모아요.","하나로 고쳐요.","까닭을 써요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#1','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C23',1,'mc','auto','학급 토의의 첫 절차는 무엇인가요?',ARRAY['K5-2-u4-X23','K5-2-u4-X35']::text[],false,'{"seq":1,"concept":"K5-2-u4-C23","difficulty":1,"kind":"mc","stem":"학급 토의의 첫 절차는 무엇인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 정하기","mis":"K5-2-u4-X23"},{"t":"의견 모으기","mis":"K5-2-u4-X23"},{"t":"되돌아보기","mis":"K5-2-u4-X35"}],"explanation":["마지막 절차예요.","넷째 절차예요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#2','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C22',1,'mc','auto','학급 토의에서 절차를 안내하는 사람은 누구인가요?',ARRAY['K5-2-u4-X22','K5-2-u4-X08']::text[],false,'{"seq":2,"concept":"K5-2-u4-C22","difficulty":1,"kind":"mc","stem":"학급 토의에서 절차를 안내하는 사람은 누구인가요?","options":[{"t":"사회자","correct":true},{"t":"은서","mis":"K5-2-u4-X22"},{"t":"목소리가 가장 큰 친구","mis":"K5-2-u4-X08"},{"t":"가장 먼저 온 친구","mis":"K5-2-u4-X22"}],"explanation":["의견을 낸 친구예요.","목소리로 정하지 않아요.","사회자가 안내해요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러 학급 문제 가운데 무엇을 토의 주제로 정하면 좋을까요?"},{"who":"은서","text":"아침 활동을 아직 정하지 못한 문제가 가장 급해요. 벌써 둘째 주가 지나가거든요."},{"who":"사회자","text":"그럼 「우리 반 아침 활동 시간을 무엇으로 채울까?」로 토의해요. 각자 의견을 마련해 봅시다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#3','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C24',1,'mc','auto','의견을 검토할 기준을 정하고 장단점을 따져 합의점을 찾는 절차는 무엇인가요?',ARRAY['K5-2-u4-X24']::text[],false,'{"seq":3,"concept":"K5-2-u4-C24","difficulty":1,"kind":"mc","stem":"의견을 검토할 기준을 정하고 장단점을 따져 합의점을 찾는 절차는 무엇인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"토의 주제 정하기","mis":"K5-2-u4-X24"},{"t":"의견 마련하기","mis":"K5-2-u4-X24"},{"t":"의견 나누기","mis":"K5-2-u4-X24"}],"explanation":["첫 절차예요.","각자 의견을 쓰는 절차예요.","조정은 의견 모으기 안에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#4','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C26',1,'ox','auto','학급 토의는 몇몇 친구만 말하고 나머지는 듣기만 하면 돼요.',ARRAY['K5-2-u4-X26']::text[],false,'{"seq":4,"concept":"K5-2-u4-C26","difficulty":1,"kind":"ox","stem":"학급 토의는 몇몇 친구만 말하고 나머지는 듣기만 하면 돼요.","answer":"X","reason_options":[{"t":"반 전체의 문제라서 모두가 의견을 마련하고 참여해야 하기 때문에","correct":true},{"t":"말 잘하는 친구의 의견이 언제나 가장 좋기 때문에","mis":"K5-2-u4-X26"}],"mis":"K5-2-u4-X26","explanation":["모두의 문제예요.","말 잘하는 것이 기준이 아니에요.","모두 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#5','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C22',2,'mc','auto','은서는 어떤 까닭으로 이 문제를 주제로 하자고 했나요?',ARRAY['K5-2-u4-X04','K5-2-u4-X22','K5-2-u4-X16']::text[],false,'{"seq":5,"concept":"K5-2-u4-C22","difficulty":2,"kind":"mc","stem":"은서는 어떤 까닭으로 이 문제를 주제로 하자고 했나요?","options":[{"t":"아직 정하지 못한 채 시간이 지나 가장 급해서","correct":true},{"t":"은서가 줄넘기를 좋아해서","mis":"K5-2-u4-X04"},{"t":"사회자가 시켜서","mis":"K5-2-u4-X22"},{"t":"가장 재미있어 보여서","mis":"K5-2-u4-X16"}],"explanation":["은서가 말하지 않은 까닭이에요.","은서가 스스로 말했어요.","가장 급하다고 했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러 학급 문제 가운데 무엇을 토의 주제로 정하면 좋을까요?"},{"who":"은서","text":"아침 활동을 아직 정하지 못한 문제가 가장 급해요. 벌써 둘째 주가 지나가거든요."},{"who":"사회자","text":"그럼 「우리 반 아침 활동 시간을 무엇으로 채울까?」로 토의해요. 각자 의견을 마련해 봅시다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#6','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C25',2,'mc','auto','의견이 많을 때 칠판에 정리하는 까닭은 무엇인가요?',ARRAY['K5-2-u4-X25','K5-2-u4-X26']::text[],false,'{"seq":6,"concept":"K5-2-u4-C25","difficulty":2,"kind":"mc","stem":"의견이 많을 때 칠판에 정리하는 까닭은 무엇인가요?","options":[{"t":"모두가 의견과 장단점을 한눈에 보고 견줄 수 있어서","correct":true},{"t":"칠판을 꾸미려고","mis":"K5-2-u4-X25"},{"t":"글씨 연습을 하려고","mis":"K5-2-u4-X25"},{"t":"말로 하면 시끄러워서","mis":"K5-2-u4-X26"}],"explanation":["꾸미려는 것이 아니에요.","연습하려는 것이 아니에요.","한눈에 보고 견줘요."],"asset":{"type":"passage","lines":["책 읽기 — 장점: 조용히 하루를 연다 · 단점: 책이 없으면 할 게 없다","줄넘기 — 장점: 몸이 깨어나 집중한다 · 단점: 비 오는 날은 못 한다","낱말 놀이 — 장점: 모두 함께 웃는다 · 단점: 매일 하면 지루해진다","합의점 — 요일마다 돌아가며 하고, 비 오는 날은 책 읽기를 한다"],"title":"칠판에 정리한 의견 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#7','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C23',2,'match','auto','학급 토의 절차와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C23","difficulty":2,"kind":"match","stem":"학급 토의 절차와 하는 일을 알맞게 이으세요.","pairs":[{"l":"의견 마련하기","r":"주제에 맞는 의견과 까닭을 각자 쓰기"},{"l":"의견 나누기","r":"마련한 의견을 발표하고 질문하기"},{"l":"의견 정하기","r":"실천할 의견을 정하기"}],"mis":"K5-2-u4-X23","explanation":["각자 마련해요.","발표하고 물어요.","실천할 의견을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#8','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C27',2,'error','auto','회의와 토의에 대한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X27','K5-2-u4-X14','K5-2-u4-X24']::text[],false,'{"seq":8,"concept":"K5-2-u4-C27","difficulty":2,"kind":"error","stem":"회의와 토의에 대한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「토의도 언제나 손을 들어 많은 쪽으로 바로 정해.」","correct":true,"mis_target":"K5-2-u4-X27"},{"t":"「회의는 손을 들어 많은 쪽으로 정하는 경우가 많아.」","mis":"K5-2-u4-X14"},{"t":"「토의는 의견을 조정해 합의된 쪽으로 정해.」","mis":"K5-2-u4-X24"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","토의는 조정해 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#9','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C24',2,'mc','auto','칠판의 합의점은 줄넘기 의견의 어떤 단점을 메웠나요?',ARRAY['K5-2-u4-X09','K5-2-u4-X10']::text[],false,'{"seq":9,"concept":"K5-2-u4-C24","difficulty":2,"kind":"mc","stem":"칠판의 합의점은 줄넘기 의견의 어떤 단점을 메웠나요?","options":[{"t":"비 오는 날에는 할 수 없는 점","correct":true},{"t":"책이 없으면 할 게 없는 점","mis":"K5-2-u4-X09"},{"t":"매일 하면 지루해지는 점","mis":"K5-2-u4-X09"},{"t":"몸이 깨어나는 점","mis":"K5-2-u4-X10"}],"explanation":["책 읽기의 단점이에요.","낱말 놀이의 단점이에요.","비 오는 날은 책 읽기로 메웠어요."],"asset":{"type":"passage","lines":["책 읽기 — 장점: 조용히 하루를 연다 · 단점: 책이 없으면 할 게 없다","줄넘기 — 장점: 몸이 깨어나 집중한다 · 단점: 비 오는 날은 못 한다","낱말 놀이 — 장점: 모두 함께 웃는다 · 단점: 매일 하면 지루해진다","합의점 — 요일마다 돌아가며 하고, 비 오는 날은 책 읽기를 한다"],"title":"칠판에 정리한 의견 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#10','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C28',3,'mc','auto','반이 「요일마다 돌아가며 하기」로 정했는데 은서는 「줄넘기 날만 하겠다.」고 했어요. 은서에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X01']::text[],false,'{"seq":10,"concept":"K5-2-u4-C28","difficulty":3,"kind":"mc","stem":"반이 「요일마다 돌아가며 하기」로 정했는데 은서는 「줄넘기 날만 하겠다.」고 했어요. 은서에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「함께 정한 절차대로 같이 해 보고, 문제가 있으면 다시 토의하자.」","correct":true},{"t":"「네 마음대로 해도 돼.」","mis":"K5-2-u4-X28"},{"t":"「한 번 정했으니 영원히 못 바꿔.」","mis":"K5-2-u4-X28"},{"t":"「네 의견은 틀렸어.」","mis":"K5-2-u4-X01"}],"explanation":["함께 정한 것은 함께 실천해요.","다시 토의할 수 있어요.","받아들이고, 필요하면 다시 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#1','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C23',2,'mc','auto','학급 토의 절차를 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['K5-2-u4-X23']::text[],false,'{"seq":1,"concept":"K5-2-u4-C23","difficulty":2,"kind":"mc","stem":"학급 토의 절차를 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기","correct":true},{"t":"의견 마련하기 → 주제 정하기 → 의견 모으기 → 의견 나누기 → 의견 정하기","mis":"K5-2-u4-X23"},{"t":"주제 정하기 → 의견 정하기 → 의견 나누기 → 의견 마련하기 → 의견 모으기","mis":"K5-2-u4-X23"},{"t":"주제 정하기 → 의견 나누기 → 의견 정하기","mis":"K5-2-u4-X23"}],"explanation":["주제가 먼저예요.","정하기는 마지막이에요.","다섯 절차를 모두 거쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#2','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C27',2,'ox','auto','회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 의견을 조정해 합의해서 정해요.',ARRAY['K5-2-u4-X27']::text[],false,'{"seq":2,"concept":"K5-2-u4-C27","difficulty":2,"kind":"ox","stem":"회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 의견을 조정해 합의해서 정해요.","answer":"O","reason_options":[{"t":"두 말하기는 정하는 방법이 다르기 때문에","correct":true},{"t":"회의와 토의는 이름만 다르고 정하는 방법이 똑같기 때문에","mis":"K5-2-u4-X27"}],"mis":"K5-2-u4-X27","explanation":["정하는 방법이 달라요.","토의는 조정해요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#3','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C26',3,'mc','auto','학급 토의에서 늘 같은 친구만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X22']::text[],false,'{"seq":3,"concept":"K5-2-u4-C26","difficulty":3,"kind":"mc","stem":"학급 토의에서 늘 같은 친구만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의견을 마련할 시간을 주고 아직 말하지 않은 친구에게 차례를 준다","correct":true},{"t":"발표 잘하는 친구에게 계속 맡긴다","mis":"K5-2-u4-X26"},{"t":"조용한 친구는 의견이 없다고 여긴다","mis":"K5-2-u4-X26"},{"t":"사회자가 의견을 대신 정한다","mis":"K5-2-u4-X22"}],"explanation":["몇몇 친구만 말하게 돼요.","조용한 친구도 생각이 있어요.","여러 친구가 말하게 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#4','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C22',3,'mc','auto','사회자의 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X22','K5-2-u4-X25','K5-2-u4-X26']::text[],false,'{"seq":4,"concept":"K5-2-u4-C22","difficulty":3,"kind":"mc","stem":"사회자의 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"자기가 좋아하는 의견으로 정해 버리기","correct":true},{"t":"절차를 안내하기","mis":"K5-2-u4-X22"},{"t":"나온 의견을 정리하기","mis":"K5-2-u4-X25"},{"t":"여러 친구가 말하도록 돕기","mis":"K5-2-u4-X26"}],"explanation":["사회자의 일이에요.","사회자의 일이에요.","사회자는 대신 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#5','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C28',3,'error','auto','학급에서 정한 의견을 실천한 뒤의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X13','K5-2-u4-X20']::text[],false,'{"seq":5,"concept":"K5-2-u4-C28","difficulty":3,"kind":"error","stem":"학급에서 정한 의견을 실천한 뒤의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘 안 되지만 한 번 정한 거니 절대 바꾸면 안 돼.」","correct":true,"mis_target":"K5-2-u4-X28"},{"t":"「해 보니 비 오는 날이 문제였어. 다시 토의해 보자.」","mis":"K5-2-u4-X13"},{"t":"「내 의견과 달랐지만 함께 정한 거라 열심히 했어.」","mis":"K5-2-u4-X20"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","잘 안 되면 다시 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#6','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C25',3,'mc','auto','반 친구들의 의견이 계속 쏟아져 정리가 안 될 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X25']::text[],false,'{"seq":6,"concept":"K5-2-u4-C25","difficulty":3,"kind":"mc","stem":"반 친구들의 의견이 계속 쏟아져 정리가 안 될 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"칠판에 의견을 적고 비슷한 의견끼리 묶어 기준과 함께 본다","correct":true},{"t":"목소리 큰 의견 하나만 적는다","mis":"K5-2-u4-X08"},{"t":"정리하지 말고 계속 말한다","mis":"K5-2-u4-X25"},{"t":"처음 말한 의견으로 정한다","mis":"K5-2-u4-X08"}],"explanation":["목소리로 고르지 않아요.","정리해야 견줘요.","한눈에 보이게 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#7','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C24',3,'mc','auto','앞에서 배운 「의견 조정하기」가 들어 있는 학급 토의 절차는 어느 것인가요?',ARRAY['K5-2-u4-X24','K5-2-u4-X23']::text[],false,'{"seq":7,"concept":"K5-2-u4-C24","difficulty":3,"kind":"mc","stem":"앞에서 배운 「의견 조정하기」가 들어 있는 학급 토의 절차는 어느 것인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"의견 마련하기","mis":"K5-2-u4-X24"},{"t":"토의 주제 정하기","mis":"K5-2-u4-X24"},{"t":"의견 정하기","mis":"K5-2-u4-X23"}],"explanation":["각자 쓰는 절차예요.","첫 절차예요.","의견 모으기 안에 조정이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#8','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C23',4,'essay','teacher','우리 반에서 풀고 싶은 학급 문제를 하나 골라 토의 주제로 바꾸고, 학급 토의 절차에 따라 무엇을 할지 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C23","difficulty":4,"kind":"essay","stem":"우리 반에서 풀고 싶은 학급 문제를 하나 골라 토의 주제로 바꾸고, 학급 토의 절차에 따라 무엇을 할지 차례대로 쓰세요.","answer_guide":{"answer":"예: 주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까? 먼저 주제를 함께 정하고, 각자 의견과 까닭을 쓴 뒤 발표하며 질문한다. 그다음 기준을 정해 장단점을 따지고 합의점을 찾아 의견을 모으고, 마지막으로 실천할 의견을 정한다.","scoring_points":["학급 문제를 토의 주제로 바꾸었는가","다섯 절차를 차례대로 썼는가","절차마다 할 일을 썼는가"]},"explanation":["주제로 바꿔요.","차례를 지켜요.","할 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#9','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C27',4,'essay','teacher','회의와 토의가 정하는 방법에서 어떻게 다른지 쓰고, 토의로 정하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C27","difficulty":4,"kind":"essay","stem":"회의와 토의가 정하는 방법에서 어떻게 다른지 쓰고, 토의로 정하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 서로의 의견을 조정해 합의된 쪽으로 정한다. 토의로 정하면 적은 사람의 의견이라도 까닭이 옳으면 살릴 수 있고, 모두가 받아들여 함께 실천하기 쉽다.","scoring_points":["회의의 정하는 방법을 썼는가","토의의 정하는 방법을 썼는가","토의의 좋은 점을 썼는가"]},"explanation":["회의의 방법이에요.","토의의 방법이에요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#10','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C28',4,'essay','teacher','반에서 정한 의견이 내 의견과 다를 때 어떻게 해야 하는지 까닭과 함께 쓰고, 실천해 보니 잘되지 않으면 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C28","difficulty":4,"kind":"essay","stem":"반에서 정한 의견이 내 의견과 다를 때 어떻게 해야 하는지 까닭과 함께 쓰고, 실천해 보니 잘되지 않으면 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 반 전체가 정당한 절차로 정한 의견이므로 내 의견과 달라도 받아들이고 함께 실천해야 한다. 그래야 모두가 지키며 문제를 풀 수 있다. 실천해 보니 잘되지 않으면 그 모습을 나누고 새 의견을 찾는 학급 토의를 다시 열자고 하겠다.","scoring_points":["받아들이고 실천한다고 썼는가","까닭을 썼는가","잘 안 될 때 다시 토의한다고 썼는가"]},"explanation":["받아들여요.","까닭을 써요.","다시 토의할 수 있어요."],"asset":{"type":"passage","lines":["책 읽기 — 장점: 조용히 하루를 연다 · 단점: 책이 없으면 할 게 없다","줄넘기 — 장점: 몸이 깨어나 집중한다 · 단점: 비 오는 날은 못 한다","낱말 놀이 — 장점: 모두 함께 웃는다 · 단점: 매일 하면 지루해진다","합의점 — 요일마다 돌아가며 하고, 비 오는 날은 책 읽기를 한다"],"title":"칠판에 정리한 의견 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#1','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C29',1,'mc','auto','글쓴이는 사람마다 무엇이 다르다고 했나요?',ARRAY['K5-2-u4-X29']::text[],false,'{"seq":1,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"글쓴이는 사람마다 무엇이 다르다고 했나요?","options":[{"t":"소중하게 여기는 것","correct":true},{"t":"사는 나라","mis":"K5-2-u4-X29"},{"t":"좋아하는 색깔","mis":"K5-2-u4-X29"},{"t":"키와 몸무게","mis":"K5-2-u4-X29"}],"explanation":["글에 없어요.","글에 없어요.","글 첫 줄에 나와요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#2','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C30',1,'mc','auto','글쓴이가 바라는 것은 무엇인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31','K5-2-u4-X29']::text[],false,'{"seq":2,"concept":"K5-2-u4-C30","difficulty":1,"kind":"mc","stem":"글쓴이가 바라는 것은 무엇인가요?","options":[{"t":"서로 조금씩 양보할 방법을 함께 찾기","correct":true},{"t":"누가 옳은지 끝까지 겨루기","mis":"K5-2-u4-X30"},{"t":"부딪치는 일은 모른 척하기","mis":"K5-2-u4-X31"},{"t":"소중한 것을 하나로 똑같이 맞추기","mis":"K5-2-u4-X29"}],"explanation":["겨루기보다 양보예요.","모른 척하지 않아요.","글 마지막 줄에 나와요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#3','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C29',1,'mc','auto','글에서 공원 산책길에서 부딪치는 두 사람은 누구인가요?',ARRAY['K5-2-u4-X06']::text[],false,'{"seq":3,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"글에서 공원 산책길에서 부딪치는 두 사람은 누구인가요?","options":[{"t":"자전거를 타는 사람과 걷는 사람","correct":true},{"t":"공을 차는 아이와 쉬고 싶은 이웃","mis":"K5-2-u4-X06"},{"t":"가게 주인과 손님","mis":"K5-2-u4-X06"},{"t":"선생님과 학생","mis":"K5-2-u4-X06"}],"explanation":["놀이터 장면이에요.","글에 없어요.","산책길 장면을 봐요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#4','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C31',1,'ox','auto','우리 주변의 문제는 어른들만 풀 수 있어 어린이는 토의할 필요가 없어요.',ARRAY['K5-2-u4-X31']::text[],false,'{"seq":4,"concept":"K5-2-u4-C31","difficulty":1,"kind":"ox","stem":"우리 주변의 문제는 어른들만 풀 수 있어 어린이는 토의할 필요가 없어요.","answer":"X","reason_options":[{"t":"우리도 의견을 모아 알맞은 곳에 제안하며 풀이에 도움을 줄 수 있기 때문에","correct":true},{"t":"주변의 문제는 우리와 관련이 없기 때문에","mis":"K5-2-u4-X31"}],"mis":"K5-2-u4-X31","explanation":["우리와 관련이 있어요.","우리도 도울 수 있어요.","어린이의 토의도 힘이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#5','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C30',2,'mc','auto','준혁의 의견 「자전거를 아예 못 타게 하자」의 단점은 무엇인가요?',ARRAY['K5-2-u4-X09','K5-2-u4-X10','K5-2-u4-X06']::text[],false,'{"seq":5,"concept":"K5-2-u4-C30","difficulty":2,"kind":"mc","stem":"준혁의 의견 「자전거를 아예 못 타게 하자」의 단점은 무엇인가요?","options":[{"t":"자전거 타는 사람의 바람은 반영되지 않는다","correct":true},{"t":"걷는 사람이 더 위험해진다","mis":"K5-2-u4-X09"},{"t":"단점이 하나도 없다","mis":"K5-2-u4-X10"},{"t":"다른 의견과 똑같다","mis":"K5-2-u4-X06"}],"explanation":["오히려 안전해져요.","어느 의견이든 단점이 있어요.","한쪽 가치만 지켜요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#6','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C32',2,'mc','auto','시우가 의견을 다듬으려고 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X32','K5-2-u4-X08','K5-2-u4-X11']::text[],false,'{"seq":6,"concept":"K5-2-u4-C32","difficulty":2,"kind":"mc","stem":"시우가 의견을 다듬으려고 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산책길을 나눈 사례를 책이나 누리집에서 찾아본다","correct":true},{"t":"짐작만으로 까닭을 덧붙인다","mis":"K5-2-u4-X32"},{"t":"목소리를 크게 연습한다","mis":"K5-2-u4-X08"},{"t":"다른 친구의 의견을 깎아내린다","mis":"K5-2-u4-X11"}],"explanation":["근거가 약해요.","목소리는 관계없어요.","자료로 까닭을 다듬어요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#7','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C29',2,'match','auto','부딪치는 사람과 그 사람이 소중히 여기는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C29","difficulty":2,"kind":"match","stem":"부딪치는 사람과 그 사람이 소중히 여기는 것을 알맞게 이으세요.","pairs":[{"l":"자전거를 타는 사람","r":"시원하게 달리기"},{"l":"걷는 사람","r":"마음 놓고 천천히 걷기"},{"l":"쉬고 싶은 이웃","r":"조용한 저녁"}],"mis":"K5-2-u4-X29","explanation":["달리고 싶어요.","천천히 걷고 싶어요.","쉬고 싶어요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#8','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C30',2,'error','auto','산책길 토의를 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X29','K5-2-u4-X30']::text[],false,'{"seq":8,"concept":"K5-2-u4-C30","difficulty":2,"kind":"error","stem":"산책길 토의를 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「자전거 타는 사람이 나쁜 사람이니 못 타게 해야 해.」","correct":true,"mis_target":"K5-2-u4-X29"},{"t":"「두 사람 모두 소중히 여기는 것이 있어.」","mis":"K5-2-u4-X30"},{"t":"「서로 조금씩 양보할 방법을 찾자.」","mis":"K5-2-u4-X30"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","나쁜 사람이 아니라 가치가 달라요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#9','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C8',2,'mc','auto','산책길 토의에서 새로 더한 검토 기준은 무엇인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X16']::text[],false,'{"seq":9,"concept":"K5-2-u4-C8","difficulty":2,"kind":"mc","stem":"산책길 토의에서 새로 더한 검토 기준은 무엇인가요?","options":[{"t":"비용","correct":true},{"t":"목소리 크기","mis":"K5-2-u4-X08"},{"t":"먼저 말한 차례","mis":"K5-2-u4-X08"},{"t":"재미","mis":"K5-2-u4-X16"}],"explanation":["기준이 아니에요.","기준이 아니에요.","공원 일이라 비용을 더했어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 · 비용","자전거 금지 — 장점: 걷는 사람이 가장 안전하다","자전거 금지 — 단점: 자전거 타는 사람의 바람은 반영되지 않는다","가운데 선 — 장점: 두 쪽 모두 함께 길을 쓴다 · 단점: 안 지킬 수 있다","저녁엔 끌고 가기 — 장점: 붐빌 때 위험이 준다 · 단점: 모르는 사람이 많다","합의점 — 가운데 선을 긋고, 저녁엔 끌고 가자는 알림판을 세운다"],"title":"산책길 토의 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#10','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C33',3,'mc','auto','반에서 정한 합의점을 실천하려고 할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u4-X33','K5-2-u4-X31','K5-2-u4-X29']::text[],false,'{"seq":10,"concept":"K5-2-u4-C33","difficulty":3,"kind":"mc","stem":"반에서 정한 합의점을 실천하려고 할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"공원 관리소에 제안 글과 알림판 그림을 함께 보낸다","correct":true},{"t":"「알린다」고만 적어 둔다","mis":"K5-2-u4-X33"},{"t":"우리끼리만 알고 있는다","mis":"K5-2-u4-X31"},{"t":"자전거 타는 사람에게 소리친다","mis":"K5-2-u4-X29"}],"explanation":["누구에게 어떻게가 빠졌어요.","알려야 바뀌어요.","알맞은 곳에 제안해요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 · 비용","자전거 금지 — 장점: 걷는 사람이 가장 안전하다","자전거 금지 — 단점: 자전거 타는 사람의 바람은 반영되지 않는다","가운데 선 — 장점: 두 쪽 모두 함께 길을 쓴다 · 단점: 안 지킬 수 있다","저녁엔 끌고 가기 — 장점: 붐빌 때 위험이 준다 · 단점: 모르는 사람이 많다","합의점 — 가운데 선을 긋고, 저녁엔 끌고 가자는 알림판을 세운다"],"title":"산책길 토의 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#1','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C30',2,'ox','auto','서로 다른 가치가 부딪치면 더 옳은 쪽 하나를 골라 이기게 해야 해요.',ARRAY['K5-2-u4-X30']::text[],false,'{"seq":1,"concept":"K5-2-u4-C30","difficulty":2,"kind":"ox","stem":"서로 다른 가치가 부딪치면 더 옳은 쪽 하나를 골라 이기게 해야 해요.","answer":"X","reason_options":[{"t":"두 가치 모두 소중할 수 있어 서로 존중하며 양보할 방법을 찾아야 하기 때문에","correct":true},{"t":"토의는 옳은 쪽을 가리는 자리이기 때문에","mis":"K5-2-u4-X30"}],"mis":"K5-2-u4-X30","explanation":["둘 다 소중할 수 있어요.","가리는 자리가 아니에요.","존중하고 양보해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#2','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C31',2,'mc','auto','주변의 부딪침 가운데 우리 반 토의 주제로 고르기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31']::text[],false,'{"seq":2,"concept":"K5-2-u4-C31","difficulty":2,"kind":"mc","stem":"주변의 부딪침 가운데 우리 반 토의 주제로 고르기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 동네 공원 산책길을 함께 안전하게 쓰는 방법","correct":true},{"t":"먼 나라 큰 강의 물길을 바꾸는 방법","mis":"K5-2-u4-X16"},{"t":"어른들의 회사 일을 정하는 방법","mis":"K5-2-u4-X31"},{"t":"친구 한 명의 숙제를 정하는 방법","mis":"K5-2-u4-X16"}],"explanation":["우리가 도울 수 없어요.","우리와 관련이 적어요.","우리가 도울 수 있는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#3','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C32',3,'mc','auto','「가운데 선을 그으면 부딪칠 일이 준다」는 까닭을 더 타당하게 만드는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X32','K5-2-u4-X04','K5-2-u4-X11']::text[],false,'{"seq":3,"concept":"K5-2-u4-C32","difficulty":3,"kind":"mc","stem":"「가운데 선을 그으면 부딪칠 일이 준다」는 까닭을 더 타당하게 만드는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"선을 그은 다른 공원 사례를 자료에서 찾아 덧붙인다","correct":true},{"t":"「분명 줄어들 거야.」라고 크게 말한다","mis":"K5-2-u4-X32"},{"t":"까닭을 빼고 의견만 말한다","mis":"K5-2-u4-X04"},{"t":"다른 의견의 단점만 말한다","mis":"K5-2-u4-X11"}],"explanation":["크게 말해도 근거가 안 돼요.","까닭이 필요해요.","자료가 까닭을 받쳐 줘요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#4','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C33',3,'mc','auto','공원 관리소에 제안할 때 넣을 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X11','K5-2-u4-X33']::text[],false,'{"seq":4,"concept":"K5-2-u4-C33","difficulty":3,"kind":"mc","stem":"공원 관리소에 제안할 때 넣을 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정한 의견과 까닭, 우리가 함께할 수 있는 일","correct":true},{"t":"불평하는 말만","mis":"K5-2-u4-X15"},{"t":"다른 의견을 낸 친구 이름","mis":"K5-2-u4-X11"},{"t":"아무 설명 없이 「바꿔 주세요.」만","mis":"K5-2-u4-X33"}],"explanation":["불평만으로는 바뀌지 않아요.","이름은 필요 없어요.","의견과 까닭을 함께 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#5','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C8',3,'error','auto','산책길 토의의 기준을 정하는 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X09','K5-2-u4-X08','K5-2-u4-X07']::text[],false,'{"seq":5,"concept":"K5-2-u4-C8","difficulty":3,"kind":"error","stem":"산책길 토의의 기준을 정하는 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「기준은 어느 문제에서나 늘 세 가지로만 정해야 해.」","correct":true,"mis_target":"K5-2-u4-X09"},{"t":"「공원 일이니 돈이 얼마나 드는지도 따지자.」","mis":"K5-2-u4-X08"},{"t":"「걷는 사람과 자전거 타는 사람 모두에게 도움이 되는지 보자.」","mis":"K5-2-u4-X07"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","기준은 문제마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#6','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C30',3,'mc','auto','칠판의 합의점이 두 사람의 가치를 모두 존중한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C30","difficulty":3,"kind":"mc","stem":"칠판의 합의점이 두 사람의 가치를 모두 존중한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자전거도 탈 수 있고 걷는 사람도 안전해지기 때문에","correct":true},{"t":"자전거를 아예 못 타게 했기 때문에","mis":"K5-2-u4-X30"},{"t":"걷는 사람이 길을 비켜 주기로 했기 때문에","mis":"K5-2-u4-X30"},{"t":"아무것도 바꾸지 않았기 때문에","mis":"K5-2-u4-X31"}],"explanation":["한쪽만 지켜요.","한쪽만 양보해요.","둘 다 존중했어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 · 비용","자전거 금지 — 장점: 걷는 사람이 가장 안전하다","자전거 금지 — 단점: 자전거 타는 사람의 바람은 반영되지 않는다","가운데 선 — 장점: 두 쪽 모두 함께 길을 쓴다 · 단점: 안 지킬 수 있다","저녁엔 끌고 가기 — 장점: 붐빌 때 위험이 준다 · 단점: 모르는 사람이 많다","합의점 — 가운데 선을 긋고, 저녁엔 끌고 가자는 알림판을 세운다"],"title":"산책길 토의 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#7','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C7',3,'mc','auto','「공원에 감시하는 사람을 늘 세워 두자.」 의견을 기준으로 다시 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X07','K5-2-u4-X18']::text[],false,'{"seq":7,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"「공원에 감시하는 사람을 늘 세워 두자.」 의견을 기준으로 다시 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"효과는 클 수 있지만 비용이 많이 들어 실천하기 어렵다","correct":true},{"t":"감시하면 무조건 좋다","mis":"K5-2-u4-X10"},{"t":"기준은 따질 필요가 없다","mis":"K5-2-u4-X07"},{"t":"질문한 친구가 잘못했다","mis":"K5-2-u4-X18"}],"explanation":["단점도 있어요.","기준으로 따져요.","여러 기준으로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#8','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C29',4,'essay','teacher','우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 찾아, 두 사람이 각각 소중히 여기는 것을 쓰고 토의 주제로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C29","difficulty":4,"kind":"essay","stem":"우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 찾아, 두 사람이 각각 소중히 여기는 것을 쓰고 토의 주제로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 저녁에 아파트 놀이터에서 공놀이를 하는 아이들은 즐겁게 노는 것을, 쉬고 싶은 이웃은 조용한 저녁을 소중히 여긴다. 토의 주제 — 어떻게 하면 놀이터를 아이들과 이웃이 모두 편하게 쓸까?","scoring_points":["부딪치는 일을 찾았는가","두 사람의 가치를 각각 썼는가","방법을 묻는 토의 주제로 바꾸었는가"]},"explanation":["부딪침을 찾아요.","두 가치를 써요.","주제로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#9','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C30',4,'essay','teacher','산책길 문제에서 내가 생각하는 합의점을 쓰고, 그 합의점이 두 사람의 가치를 어떻게 존중하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C30","difficulty":4,"kind":"essay","stem":"산책길 문제에서 내가 생각하는 합의점을 쓰고, 그 합의점이 두 사람의 가치를 어떻게 존중하는지 쓰세요.","answer_guide":{"answer":"예: 산책길에 가운데 선을 긋고, 사람이 많은 저녁에는 자전거를 천천히 타거나 끌고 가자는 알림판을 세운다. 자전거 타는 사람은 계속 탈 수 있고, 걷는 사람은 붐비는 때에도 마음 놓고 걸을 수 있어 둘 다 존중된다.","scoring_points":["합의점을 썼는가","자전거 타는 사람의 가치를 살폈는가","걷는 사람의 가치를 살폈는가"]},"explanation":["합의점이에요.","한쪽 가치예요.","다른 쪽 가치도 살펴요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#10','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C33',4,'essay','teacher','우리 반이 주변의 문제로 정한 의견을 누구에게 어떻게 알릴지 실천 계획을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C33","difficulty":4,"kind":"essay","stem":"우리 반이 주변의 문제로 정한 의견을 누구에게 어떻게 알릴지 실천 계획을 쓰세요.","answer_guide":{"answer":"예: 공원 산책길 의견을 공원 관리소에 알리겠다. 정한 의견과 까닭, 산책길 알림판 그림을 담은 제안 편지를 반 친구들이 함께 써서 관리소 누리집에 올리고, 동네 게시판에도 알림판 그림을 붙이겠다.","scoring_points":["알릴 곳을 정했는가","알릴 방법을 썼는가","의견과 까닭을 함께 담았는가"]},"explanation":["누구에게예요.","어떻게예요.","의견과 까닭을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#1','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C34',1,'mc','auto','학교 문제 토의 여섯 단계의 마지막 단계는 무엇인가요?',ARRAY['K5-2-u4-X35']::text[],false,'{"seq":1,"concept":"K5-2-u4-C34","difficulty":1,"kind":"mc","stem":"학교 문제 토의 여섯 단계의 마지막 단계는 무엇인가요?","options":[{"t":"되돌아보기","correct":true},{"t":"토의 주제 정하기","mis":"K5-2-u4-X35"},{"t":"의견 마련하기","mis":"K5-2-u4-X35"},{"t":"의견 나누기","mis":"K5-2-u4-X35"}],"explanation":["첫 단계예요.","둘째 단계예요.","마치면 되돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#2','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C36',1,'mc','auto','두 의견을 하나로 합쳐 새 의견을 만드는 생각 도구 물음은 무엇인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":2,"concept":"K5-2-u4-C36","difficulty":1,"kind":"mc","stem":"두 의견을 하나로 합쳐 새 의견을 만드는 생각 도구 물음은 무엇인가요?","options":[{"t":"합치기","correct":true},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"순서 바꾸기","mis":"K5-2-u4-X36"},{"t":"포기하기","mis":"K5-2-u4-X36"}],"explanation":["일부를 덜어 내요.","차례를 바꿔요.","두 의견을 합쳐요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#3','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C15',1,'mc','auto','쪽지를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31']::text[],false,'{"seq":3,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"쪽지를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 수돗가 바닥을 깨끗하게 쓸까?","correct":true},{"t":"수돗가가 물바다라서 정말 싫다.","mis":"K5-2-u4-X15"},{"t":"도서관은 내 탓이 아니다.","mis":"K5-2-u4-X15"},{"t":"급식실 줄은 원래 길다.","mis":"K5-2-u4-X31"}],"explanation":["불평하는 말이에요.","탓하는 말이에요.","방법을 묻는 물음이에요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#4','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C37',1,'ox','auto','토의를 되돌아볼 때에는 누구 잘못인지 따지는 것이 가장 중요해요.',ARRAY['K5-2-u4-X37']::text[],false,'{"seq":4,"concept":"K5-2-u4-C37","difficulty":1,"kind":"ox","stem":"토의를 되돌아볼 때에는 누구 잘못인지 따지는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"잘한 점과 다음에 함께 노력할 점을 찾는 시간이기 때문에","correct":true},{"t":"잘못한 친구를 찾아야 다음 토의가 잘되기 때문에","mis":"K5-2-u4-X37"}],"mis":"K5-2-u4-X37","explanation":["탓하는 시간이 아니에요.","함께 노력할 점을 찾아요.","잘한 점도 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#5','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C35',2,'mc','auto','의견을 정한 뒤 꼭 확인할 것은 무엇인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X38']::text[],false,'{"seq":5,"concept":"K5-2-u4-C35","difficulty":2,"kind":"mc","stem":"의견을 정한 뒤 꼭 확인할 것은 무엇인가요?","options":[{"t":"이견이 없는지 확인하기","correct":true},{"t":"가장 먼저 말한 의견인지 확인하기","mis":"K5-2-u4-X08"},{"t":"선생님 의견과 같은지 확인하기","mis":"K5-2-u4-X38"},{"t":"목소리 큰 친구가 좋아하는지 확인하기","mis":"K5-2-u4-X08"}],"explanation":["차례는 관계없어요.","정해진 정답은 없어요.","모두 받아들이는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#6','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C36',2,'mc','auto','「급식실에 일찍 가자」와 「늦게 가자」가 맞설 때, 「요일마다 학년이 가는 순서를 바꾸자」는 어떤 생각 도구로 만든 의견인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":6,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"「급식실에 일찍 가자」와 「늦게 가자」가 맞설 때, 「요일마다 학년이 가는 순서를 바꾸자」는 어떤 생각 도구로 만든 의견인가요?","options":[{"t":"순서 바꾸기","correct":true},{"t":"합치기","mis":"K5-2-u4-X36"},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"줄이기","mis":"K5-2-u4-X36"}],"explanation":["두 의견을 붙인 것이 아니에요.","덜어 낸 것이 아니에요.","차례를 바꾸었어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#7','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C34',2,'match','auto','학교 문제 토의 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C34","difficulty":2,"kind":"match","stem":"학교 문제 토의 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"의견 나누기","r":"모둠에서 먼저 나누고 추려 발표하기"},{"l":"의견 정하기","r":"실천할 의견을 정하고 이견이 없는지 확인하기"},{"l":"되돌아보기","r":"잘한 점과 보완할 점 나누기"}],"mis":"K5-2-u4-X35","explanation":["모둠에서 먼저 나눠요.","정하고 확인해요.","마치고 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#8','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C37',2,'error','auto','토의를 되돌아보는 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X37','K5-2-u4-X26']::text[],false,'{"seq":8,"concept":"K5-2-u4-C37","difficulty":2,"kind":"error","stem":"토의를 되돌아보는 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「이번 토의는 다 너 때문에 망쳤어.」","correct":true,"mis_target":"K5-2-u4-X37"},{"t":"「조용한 친구도 말할 수 있게 기다려 준 점이 좋았어.」","mis":"K5-2-u4-X26"},{"t":"「다음에는 의견이 다를 때 기준으로 차분히 따져 보자.」","mis":"K5-2-u4-X37"}],"explanation":["잘한 점이에요.","함께 노력할 점이에요.","탓하는 말은 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#9','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C34',2,'mc','auto','학교 문제 토의에서 의견 나누기를 모둠에서 먼저 하면 좋은 점은 무엇인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X35','K5-2-u4-X23']::text[],false,'{"seq":9,"concept":"K5-2-u4-C34","difficulty":2,"kind":"mc","stem":"학교 문제 토의에서 의견 나누기를 모둠에서 먼저 하면 좋은 점은 무엇인가요?","options":[{"t":"여러 의견을 추려 반에서 더 잘 견줄 수 있다","correct":true},{"t":"모둠 밖 친구는 말하지 않아도 된다","mis":"K5-2-u4-X26"},{"t":"되돌아보기를 안 해도 된다","mis":"K5-2-u4-X35"},{"t":"절차를 건너뛸 수 있다","mis":"K5-2-u4-X23"}],"explanation":["모두 말해요.","되돌아보기는 꼭 해요.","추려서 견주기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#10','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C28',3,'mc','auto','「수돗가 물바다」 문제로 정한 의견을 실천했는데 여전히 물이 흥건해요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X37','K5-2-u4-X14']::text[],false,'{"seq":10,"concept":"K5-2-u4-C28","difficulty":3,"kind":"mc","stem":"「수돗가 물바다」 문제로 정한 의견을 실천했는데 여전히 물이 흥건해요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"실천한 모습을 나누고 새 의견을 찾는 토의를 다시 연다","correct":true},{"t":"한 번 정했으니 그대로 둔다","mis":"K5-2-u4-X28"},{"t":"의견을 정한 친구 탓을 한다","mis":"K5-2-u4-X37"},{"t":"토의는 쓸모없다고 여긴다","mis":"K5-2-u4-X14"}],"explanation":["다시 고칠 수 있어요.","탓하지 않아요.","다시 토의하는 것도 조정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#1','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C35',2,'ox','auto','의견을 정한 뒤에는 이견이 없는지 확인해요.',ARRAY['K5-2-u4-X34']::text[],false,'{"seq":1,"concept":"K5-2-u4-C35","difficulty":2,"kind":"ox","stem":"의견을 정한 뒤에는 이견이 없는지 확인해요.","answer":"O","reason_options":[{"t":"모두가 받아들여야 함께 실천할 수 있기 때문에","correct":true},{"t":"이견이 있어도 이미 정했으니 상관없기 때문에","mis":"K5-2-u4-X34"}],"mis":"K5-2-u4-X34","explanation":["확인해야 해요.","함께 실천하려면 필요해요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#2','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C36',2,'mc','auto','합의점이 보이지 않을 때 생각 도구 물음을 던지는 까닭은 무엇인가요?',ARRAY['K5-2-u4-X36','K5-2-u4-X12','K5-2-u4-X11']::text[],false,'{"seq":2,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"합의점이 보이지 않을 때 생각 도구 물음을 던지는 까닭은 무엇인가요?","options":[{"t":"막힌 생각을 풀어 새 의견을 떠올리려고","correct":true},{"t":"토의를 빨리 끝내려고","mis":"K5-2-u4-X36"},{"t":"한 의견만 고르려고","mis":"K5-2-u4-X12"},{"t":"친구 의견을 깎아내리려고","mis":"K5-2-u4-X11"}],"explanation":["빨리 끝내려는 게 아니에요.","새 의견을 만들어요.","막힐 때 던지는 물음이에요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#3','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C37',3,'mc','auto','되돌아보기에서 「의견이 다를 때 목소리가 커졌던 점」을 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X37','K5-2-u4-X08','K5-2-u4-X35']::text[],false,'{"seq":3,"concept":"K5-2-u4-C37","difficulty":3,"kind":"mc","stem":"되돌아보기에서 「의견이 다를 때 목소리가 커졌던 점」을 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「다음에는 의견이 맞지 않아도 차분히 기준으로 따져 보자.」","correct":true},{"t":"「누가 소리쳤는지 이름을 말해 봐.」","mis":"K5-2-u4-X37"},{"t":"「목소리 큰 쪽이 이겼으니 괜찮아.」","mis":"K5-2-u4-X08"},{"t":"「되돌아보기는 시간 낭비야.」","mis":"K5-2-u4-X35"}],"explanation":["탓하는 말이에요.","목소리로 정하지 않아요.","함께 노력할 점으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#4','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C36',3,'mc','auto','「반납대 옆에 칸 그림을 붙이자」와 「책 정리 당번을 정하자」를 「합치기」로 만든 의견으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X03','K5-2-u4-X08']::text[],false,'{"seq":4,"concept":"K5-2-u4-C36","difficulty":3,"kind":"mc","stem":"「반납대 옆에 칸 그림을 붙이자」와 「책 정리 당번을 정하자」를 「합치기」로 만든 의견으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"칸 그림을 붙이고, 당번이 하루 한 번 그림대로 꽂혔는지 살핀다","correct":true},{"t":"당번만 정하고 그림은 버린다","mis":"K5-2-u4-X12"},{"t":"둘 다 버리고 새로 시작한다","mis":"K5-2-u4-X03"},{"t":"먼저 나온 의견으로 정한다","mis":"K5-2-u4-X08"}],"explanation":["한쪽을 버렸어요.","둘 다 살려요.","두 의견을 합쳤어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#5','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C34',3,'error','auto','학교 문제 토의 계획이에요. 가장 알맞지 않은 계획은 어느 것인가요?',ARRAY['K5-2-u4-X35','K5-2-u4-X34']::text[],false,'{"seq":5,"concept":"K5-2-u4-C34","difficulty":3,"kind":"error","stem":"학교 문제 토의 계획이에요. 가장 알맞지 않은 계획은 어느 것인가요?","options":[{"t":"「의견을 정하면 바로 끝내고 되돌아보기는 하지 말자.」","correct":true,"mis_target":"K5-2-u4-X35"},{"t":"「의견 나누기는 모둠에서 먼저 하자.」","mis":"K5-2-u4-X34"},{"t":"「정한 뒤 이견이 없는지 물어보자.」","mis":"K5-2-u4-X34"}],"explanation":["알맞은 계획이에요.","알맞은 계획이에요.","되돌아보기까지 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#6','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C31',3,'mc','auto','학교 지도 쪽지를 보고 토의 주제를 고르는 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C31","difficulty":3,"kind":"mc","stem":"학교 지도 쪽지를 보고 토의 주제를 고르는 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반이 매일 쓰고 직접 바꿀 수 있는 수돗가 문제부터 하자.」","correct":true},{"t":"「학교 건물을 새로 짓는 문제를 하자.」","mis":"K5-2-u4-X16"},{"t":"「쪽지는 다 불평이니 무시하자.」","mis":"K5-2-u4-X31"},{"t":"「제일 웃긴 쪽지를 고르자.」","mis":"K5-2-u4-X16"}],"explanation":["우리가 풀 수 없어요.","쪽지가 문제를 알려 줘요.","관련 있고 직접 풀 수 있어요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#7','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C38',3,'mc','auto','토의에서 처음 나온 의견보다 합의점이 더 나아지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X38','K5-2-u4-X08','K5-2-u4-X12']::text[],false,'{"seq":7,"concept":"K5-2-u4-C38","difficulty":3,"kind":"mc","stem":"토의에서 처음 나온 의견보다 합의점이 더 나아지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 질문하고 장단점을 따지며 보완했기 때문에","correct":true},{"t":"선생님이 정답을 알려 주었기 때문에","mis":"K5-2-u4-X38"},{"t":"목소리가 큰 친구가 정했기 때문에","mis":"K5-2-u4-X08"},{"t":"한 의견을 그대로 골랐기 때문에","mis":"K5-2-u4-X12"}],"explanation":["정답이 정해진 게 아니에요.","목소리로 정하지 않아요.","과정에서 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#8','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C34',4,'essay','teacher','쪽지 하나를 골라 토의 주제를 정하고, 내 의견과 까닭을 쓴 뒤 학교 문제 토의 단계 가운데 두 단계에서 무엇을 할지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C34","difficulty":4,"kind":"essay","stem":"쪽지 하나를 골라 토의 주제를 정하고, 내 의견과 까닭을 쓴 뒤 학교 문제 토의 단계 가운데 두 단계에서 무엇을 할지 쓰세요.","answer_guide":{"answer":"예: 주제 — 어떻게 하면 도서관 책을 제자리에 꽂을까? 의견 — 반납대 옆에 칸 그림을 붙이자. 까닭 — 어디에 꽂을지 바로 알 수 있다. 의견 모으기 단계에서는 기준을 정해 장단점을 따지고, 되돌아보기 단계에서는 잘한 점과 보완할 점을 나누겠다.","scoring_points":["주제를 방법을 묻는 꼴로 썼는가","의견과 까닭을 썼는가","두 단계에서 할 일을 썼는가"]},"explanation":["주제를 정해요.","의견과 까닭이에요.","단계마다 할 일을 써요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#9','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C36',4,'essay','teacher','서로 맞선 두 의견을 하나 떠올려 쓰고, 생각 도구 물음 가운데 하나를 골라 새 의견으로 만들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C36","difficulty":4,"kind":"essay","stem":"서로 맞선 두 의견을 하나 떠올려 쓰고, 생각 도구 물음 가운데 하나를 골라 새 의견으로 만들어 쓰세요.","answer_guide":{"answer":"예: 쉬는 시간에 「운동하자」와 「책을 읽자」가 맞섰다. 순서 바꾸기 물음으로 앞 쉬는 시간에는 몸을 움직이고 뒤 쉬는 시간에는 책을 읽기로 하면 두 의견을 모두 살릴 수 있다.","scoring_points":["맞선 두 의견을 썼는가","생각 도구 하나를 밝혔는가","두 의견을 살린 새 의견을 썼는가"]},"explanation":["맞선 의견이에요.","도구를 골라요.","새 의견을 만들어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#10','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C37',4,'essay','teacher','모둠 토의를 되돌아보며 잘한 점과 보완할 점을 하나씩 쓰고, 다음 토의에서 함께 노력할 다짐을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C37","difficulty":4,"kind":"essay","stem":"모둠 토의를 되돌아보며 잘한 점과 보완할 점을 하나씩 쓰고, 다음 토의에서 함께 노력할 다짐을 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 기준을 먼저 정해서 차분하게 따질 수 있었다. 보완할 점 — 시간이 모자라 조용한 친구의 의견을 다 듣지 못했다. 다짐 — 다음 토의에서는 모두 한 번씩 말할 수 있게 차례를 정하자.","scoring_points":["잘한 점을 썼는가","보완할 점을 탓하지 않고 썼는가","함께 노력할 다짐을 썼는가"]},"explanation":["잘한 점이에요.","보완할 점이에요.","함께 할 다짐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#1','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C2',1,'mc','auto','여럿이 함께 문제를 풀 방법을 찾는 말하기는 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X06']::text[],false,'{"seq":1,"concept":"K5-2-u4-C2","difficulty":1,"kind":"mc","stem":"여럿이 함께 문제를 풀 방법을 찾는 말하기는 어느 것인가요?","options":[{"t":"토의","correct":true},{"t":"연설","mis":"K5-2-u4-X02"},{"t":"토론","mis":"K5-2-u4-X02"},{"t":"면담","mis":"K5-2-u4-X06"}],"explanation":["혼자 주장해요.","맞서서 겨뤄요.","함께 방법을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#2','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C39',1,'mc','auto','어려운 말이나 외래어를 알기 쉬운 우리말로 바꾼 말을 무엇이라고 하나요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":2,"concept":"K5-2-u4-C39","difficulty":1,"kind":"mc","stem":"어려운 말이나 외래어를 알기 쉬운 우리말로 바꾼 말을 무엇이라고 하나요?","options":[{"t":"순화어","correct":true},{"t":"외래어","mis":"K5-2-u4-X39"},{"t":"방언","mis":"K5-2-u4-X39"},{"t":"줄임말","mis":"K5-2-u4-X39"}],"explanation":["바꾸기 전 말이에요.","지역의 말이에요.","쉬운 우리말로 다듬은 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#3','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C7',1,'mc','auto','의견을 조정할 때 가장 먼저 하는 일은 어느 것인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X08','K5-2-u4-X14']::text[],false,'{"seq":3,"concept":"K5-2-u4-C7","difficulty":1,"kind":"mc","stem":"의견을 조정할 때 가장 먼저 하는 일은 어느 것인가요?","options":[{"t":"의견을 검토할 기준 마련하기","correct":true},{"t":"합의점 찾기","mis":"K5-2-u4-X13"},{"t":"목소리 큰 의견 고르기","mis":"K5-2-u4-X08"},{"t":"손을 들어 정하기","mis":"K5-2-u4-X14"}],"explanation":["마지막 차례예요.","기준이 아니에요.","기준이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#4','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C23',1,'mc','auto','학급 토의의 첫 절차는 어느 것인가요?',ARRAY['K5-2-u4-X23','K5-2-u4-X35']::text[],false,'{"seq":4,"concept":"K5-2-u4-C23","difficulty":1,"kind":"mc","stem":"학급 토의의 첫 절차는 어느 것인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 정하기","mis":"K5-2-u4-X23"},{"t":"의견 모으기","mis":"K5-2-u4-X23"},{"t":"되돌아보기","mis":"K5-2-u4-X35"}],"explanation":["마지막이에요.","넷째예요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#5','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C6',1,'mc','auto','토의 「블록 놀이 자리」에서 풀어야 할 문제는 어느 것인가요?',ARRAY['K5-2-u4-X06']::text[],false,'{"seq":5,"concept":"K5-2-u4-C6","difficulty":1,"kind":"mc","stem":"토의 「블록 놀이 자리」에서 풀어야 할 문제는 어느 것인가요?","options":[{"t":"블록 놀이 자리가 좁고 시끄러워 다툼이 생기는 것","correct":true},{"t":"블록이 너무 적은 것","mis":"K5-2-u4-X06"},{"t":"쉬는 시간이 너무 짧은 것","mis":"K5-2-u4-X06"},{"t":"책 읽는 자리가 없는 것","mis":"K5-2-u4-X06"}],"explanation":["토의에 없어요.","토의에 없어요.","사회자가 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#6','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C15',1,'mc','auto','토의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"토의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 교실 뒤 놀이 자리를 사이좋게 쓸까?","correct":true},{"t":"놀이 자리가 시끄러워서 싫다.","mis":"K5-2-u4-X15"},{"t":"놀이 자리는 누가 어질렀지?","mis":"K5-2-u4-X15"},{"t":"놀이 자리는 원래 좁다.","mis":"K5-2-u4-X31"}],"explanation":["불평이에요.","탓하는 물음이에요.","방법을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#7','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C17',1,'mc','auto','친구 의견을 들으며 궁금한 점을 묻는 것은 어느 것인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":7,"concept":"K5-2-u4-C17","difficulty":1,"kind":"mc","stem":"친구 의견을 들으며 궁금한 점을 묻는 것은 어느 것인가요?","options":[{"t":"질문하며 듣기","correct":true},{"t":"맞장구만 치기","mis":"K5-2-u4-X21"},{"t":"끼어들어 말 끊기","mis":"K5-2-u4-X18"},{"t":"못 들은 척하기","mis":"K5-2-u4-X17"}],"explanation":["묻지 않아요.","공손하지 않아요.","물으며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#8','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C29',1,'mc','auto','「소중한 것이 서로 다를 때」에서 부딪침이 생기는 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X29']::text[],false,'{"seq":8,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"「소중한 것이 서로 다를 때」에서 부딪침이 생기는 까닭은 어느 것인가요?","options":[{"t":"사람마다 소중하게 여기는 것이 달라서","correct":true},{"t":"한쪽이 나쁜 사람이라서","mis":"K5-2-u4-X29"},{"t":"규칙이 하나도 없어서","mis":"K5-2-u4-X29"},{"t":"모두 같은 것을 좋아해서","mis":"K5-2-u4-X29"}],"explanation":["나쁜 사람이 아니에요.","글에 없어요.","가치가 달라서예요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#9','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C15',2,'mc','auto','「꿈나무반 학급 토의 기록장」의 토의 주제는 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X06']::text[],false,'{"seq":9,"concept":"K5-2-u4-C15","difficulty":2,"kind":"mc","stem":"「꿈나무반 학급 토의 기록장」의 토의 주제는 어느 것인가요?","options":[{"t":"어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","correct":true},{"t":"화분은 누가 시들게 했을까?","mis":"K5-2-u4-X15"},{"t":"창가를 어떻게 넓힐까?","mis":"K5-2-u4-X06"},{"t":"이름표를 어디서 살까?","mis":"K5-2-u4-X06"}],"explanation":["탓하는 물음이에요.","주제가 아니에요.","기록장 첫 줄이에요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#10','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C9',2,'mc','auto','「네 명까지만 놀자」 의견의 단점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10']::text[],false,'{"seq":10,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"「네 명까지만 놀자」 의견의 단점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"놀이마다 알맞은 인원이 달라 몇 명으로 할지 정하기 어렵다","correct":true},{"t":"자리가 넉넉해진다","mis":"K5-2-u4-X10"},{"t":"소리가 줄어든다","mis":"K5-2-u4-X10"},{"t":"단점이 하나도 없다","mis":"K5-2-u4-X10"}],"explanation":["장점이에요.","장점이에요.","어느 의견이든 단점이 있어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#11','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C12',2,'mc','auto','블록 토의의 합의점 「매트 안에서 네 명까지, 규칙 안내판 붙이기」는 어떻게 만든 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X08','K5-2-u4-X03']::text[],false,'{"seq":11,"concept":"K5-2-u4-C12","difficulty":2,"kind":"mc","stem":"블록 토의의 합의점 「매트 안에서 네 명까지, 규칙 안내판 붙이기」는 어떻게 만든 것인가요?","options":[{"t":"두 의견의 장점을 합쳤다","correct":true},{"t":"한 의견만 그대로 골랐다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 의견을 따랐다","mis":"K5-2-u4-X08"},{"t":"세 의견을 모두 버렸다","mis":"K5-2-u4-X03"}],"explanation":["합쳤어요.","목소리로 정하지 않아요.","하윤이와 나은이 의견을 합쳤어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#12','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C27',2,'mc','auto','회의와 토의가 정하는 방법을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u4-X27','K5-2-u4-X22']::text[],false,'{"seq":12,"concept":"K5-2-u4-C27","difficulty":2,"kind":"mc","stem":"회의와 토의가 정하는 방법을 바르게 말한 것은 어느 것인가요?","options":[{"t":"회의는 손을 들어 많은 쪽으로, 토의는 조정해 합의된 쪽으로 정한다","correct":true},{"t":"회의와 토의 모두 늘 손을 들어 정한다","mis":"K5-2-u4-X27"},{"t":"토의는 선생님이 대신 정한다","mis":"K5-2-u4-X22"},{"t":"회의는 아무것도 정하지 않는다","mis":"K5-2-u4-X27"}],"explanation":["정하는 방법이 달라요.","토의는 함께 정해요.","회의도 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#13','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C39',2,'mc','auto','「여행 가이드」를 순화어로 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":13,"concept":"K5-2-u4-C39","difficulty":2,"kind":"mc","stem":"「여행 가이드」를 순화어로 바꾼 것은 어느 것인가요?","options":[{"t":"여행 안내원","correct":true},{"t":"전시 기획자","mis":"K5-2-u4-X39"},{"t":"책 소개 영상","mis":"K5-2-u4-X39"},{"t":"개봉","mis":"K5-2-u4-X39"}],"explanation":["큐레이터예요.","북 트레일러예요.","안내하는 사람이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#14','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C36',2,'mc','auto','「앞 쉬는 시간에는 몸을 움직이고 뒤 쉬는 시간에는 책을 읽자」는 어떤 생각 도구로 만든 의견인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":14,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"「앞 쉬는 시간에는 몸을 움직이고 뒤 쉬는 시간에는 책을 읽자」는 어떤 생각 도구로 만든 의견인가요?","options":[{"t":"순서 바꾸기","correct":true},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"줄이기","mis":"K5-2-u4-X36"},{"t":"포기하기","mis":"K5-2-u4-X36"}],"explanation":["덜어 내지 않았어요.","줄이지 않았어요.","차례를 나누었어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#15','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C7',2,'mc','auto','여러 의견을 견줄 때 쓰는 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X07']::text[],false,'{"seq":15,"concept":"K5-2-u4-C7","difficulty":2,"kind":"mc","stem":"여러 의견을 견줄 때 쓰는 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"가장 먼저 말한 의견인가?","correct":true},{"t":"실천할 수 있는가?","mis":"K5-2-u4-X07"},{"t":"효과적인가?","mis":"K5-2-u4-X07"},{"t":"여러 사람에게 도움이 되는가?","mis":"K5-2-u4-X07"}],"explanation":["알맞은 기준이에요.","알맞은 기준이에요.","말한 차례는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#16','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C37',2,'mc','auto','토의를 되돌아볼 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X37','K5-2-u4-X35','K5-2-u4-X08']::text[],false,'{"seq":16,"concept":"K5-2-u4-C37","difficulty":2,"kind":"mc","stem":"토의를 되돌아볼 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「질문 덕분에 의견이 단단해졌어. 다음엔 시간을 나누어 모두 말하자.」","correct":true},{"t":"「이번 토의는 너 때문에 망쳤어.」","mis":"K5-2-u4-X37"},{"t":"「되돌아보기는 시간 낭비야.」","mis":"K5-2-u4-X35"},{"t":"「목소리 큰 쪽이 이겼으니 됐어.」","mis":"K5-2-u4-X08"}],"explanation":["탓하는 말이에요.","꼭 필요해요.","잘한 점과 다짐을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#17','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C19',3,'mc','auto','기록장의 합의점은 세 의견을 어떻게 살렸나요?',ARRAY['K5-2-u4-X19','K5-2-u4-X10','K5-2-u4-X20']::text[],false,'{"seq":17,"concept":"K5-2-u4-C19","difficulty":3,"kind":"mc","stem":"기록장의 합의점은 세 의견을 어떻게 살렸나요?","options":[{"t":"이름표 · 당번 · 창가 의견의 장점을 모두 살리고 단점을 메웠다","correct":true},{"t":"지안이 의견만 그대로 골랐다","mis":"K5-2-u4-X19"},{"t":"로운이 의견은 단점이 있어 버렸다","mis":"K5-2-u4-X10"},{"t":"태린이 의견이 이겨서 그대로 정했다","mis":"K5-2-u4-X20"}],"explanation":["셋 다 살렸어요.","줄여서 살렸어요.","모아서 고쳤어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#18','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C11',3,'mc','auto','블록 토의에서 세 의견의 장점을 살린 합의점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X12','K5-2-u4-X08']::text[],false,'{"seq":18,"concept":"K5-2-u4-C11","difficulty":3,"kind":"mc","stem":"블록 토의에서 세 의견의 장점을 살린 합의점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"매트 안에서 네 명까지 놀고, 작은 목소리 규칙을 안내판으로 붙인다","correct":true},{"t":"블록 놀이를 아예 없앤다","mis":"K5-2-u4-X30"},{"t":"하윤이 의견만 그대로 따른다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 모둠이 먼저 논다","mis":"K5-2-u4-X08"}],"explanation":["모두의 바람을 지우지 않아요.","하나만 고르지 않아요.","장점을 모았어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#19','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C26',3,'mc','auto','학급 토의에서 늘 같은 친구들만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X22']::text[],false,'{"seq":19,"concept":"K5-2-u4-C26","difficulty":3,"kind":"mc","stem":"학급 토의에서 늘 같은 친구들만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의견을 마련할 시간을 주고 아직 말하지 않은 친구에게 차례를 준다","correct":true},{"t":"발표 잘하는 친구에게 계속 맡긴다","mis":"K5-2-u4-X26"},{"t":"사회자가 대신 정한다","mis":"K5-2-u4-X22"},{"t":"조용한 친구는 의견이 없다고 여긴다","mis":"K5-2-u4-X26"}],"explanation":["몇몇만 말하게 돼요.","대신 정하지 않아요.","모두 말하게 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#20','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C30',3,'mc','auto','산책길 문제에서 두 사람의 가치를 모두 존중한 의견으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31']::text[],false,'{"seq":20,"concept":"K5-2-u4-C30","difficulty":3,"kind":"mc","stem":"산책길 문제에서 두 사람의 가치를 모두 존중한 의견으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가운데 선을 긋고 붐비는 저녁엔 자전거를 끌고 가자","correct":true},{"t":"자전거를 아예 못 타게 하자","mis":"K5-2-u4-X30"},{"t":"걷는 사람이 늘 비켜 주자","mis":"K5-2-u4-X30"},{"t":"아무것도 바꾸지 말자","mis":"K5-2-u4-X31"}],"explanation":["한쪽만 지켜요.","한쪽만 양보해요.","둘 다 존중해요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#21','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C18',3,'mc','auto','친구 의견에 빈틈이 보일 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":21,"concept":"K5-2-u4-C18","difficulty":3,"kind":"mc","stem":"친구 의견에 빈틈이 보일 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「궁금해서 묻는데, 비 오는 날에는 어떻게 해?」","correct":true},{"t":"「그 의견은 빈틈투성이야.」","mis":"K5-2-u4-X18"},{"t":"「그냥 넘어가자.」","mis":"K5-2-u4-X17"},{"t":"「그럴 줄 알았어.」","mis":"K5-2-u4-X18"}],"explanation":["공격하는 말이에요.","빈틈이 남아요.","공손하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#22','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C38',3,'mc','auto','「좋은 의견은 처음부터 정해져 있어서 찾기만 하면 된다.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X38','K5-2-u4-X08']::text[],false,'{"seq":22,"concept":"K5-2-u4-C38","difficulty":3,"kind":"mc","stem":"「좋은 의견은 처음부터 정해져 있어서 찾기만 하면 된다.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「서로 견주고 고치는 과정에서 처음보다 나은 의견이 만들어져.」","correct":true},{"t":"「맞아, 선생님이 정답을 알고 계셔.」","mis":"K5-2-u4-X38"},{"t":"「목소리 큰 친구 의견이 정답이야.」","mis":"K5-2-u4-X08"},{"t":"「처음 나온 의견이 늘 정답이야.」","mis":"K5-2-u4-X38"}],"explanation":["정답이 정해진 게 아니에요.","목소리로 정하지 않아요.","과정에서 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#23','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C11',4,'essay','teacher','토의 「블록 놀이 자리」의 세 의견 가운데 둘 이상의 장점을 살려 합의점을 쓰고, 어떤 단점을 어떻게 메웠는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C11","difficulty":4,"kind":"essay","stem":"토의 「블록 놀이 자리」의 세 의견 가운데 둘 이상의 장점을 살려 합의점을 쓰고, 어떤 단점을 어떻게 메웠는지 쓰세요.","answer_guide":{"answer":"예: 매트 안에서 한 번에 네 명까지 놀고, 작은 목소리 규칙을 안내판으로 붙인다. 인원만 정하면 꾸준히 지키기 어렵다는 단점을 안내판으로 메웠고, 규칙만 정하면 자리가 좁다는 단점을 인원 제한으로 메웠다.","scoring_points":["둘 이상의 장점을 살렸는가","합의점을 분명히 썼는가","메운 단점을 썼는가"]},"explanation":["장점을 모아요.","합의점을 써요.","단점을 어떻게 메웠는지 써요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#24','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C30',4,'essay','teacher','우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 골라 두 사람이 소중히 여기는 것을 쓰고, 둘 다 존중하는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C30","difficulty":4,"kind":"essay","stem":"우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 골라 두 사람이 소중히 여기는 것을 쓰고, 둘 다 존중하는 방법을 쓰세요.","answer_guide":{"answer":"예: 밤늦게 악기를 연습하고 싶은 이웃과 조용히 쉬고 싶은 이웃이 있다. 한 사람은 연주 실력을, 다른 사람은 편안한 휴식을 소중히 여긴다. 저녁 일찍까지만 연습하고 소리를 줄이는 깔개를 깔면 둘 다 존중할 수 있다.","scoring_points":["부딪치는 일을 골랐는가","두 사람의 가치를 썼는가","둘 다 존중하는 방법을 썼는가"]},"explanation":["부딪침을 골라요.","두 가치를 써요.","둘 다 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#25','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C9',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 의견 하나를 골라 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C9","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 의견 하나를 골라 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.","answer_guide":{"answer":"예: 태린이의 당번 의견은 효과적인가 기준으로 보면 날마다 잊지 않고 물을 줄 수 있다는 장점이 있다. 여러 사람에게 도움이 되는가 기준으로 보면 당번만 애쓰고 다른 친구는 신경 쓰지 않을 수 있다는 단점이 있다.","scoring_points":["의견 하나를 골랐는가","기준 두 가지를 밝혔는가","장점과 단점을 의견을 두고 썼는가"]},"explanation":["의견을 골라요.","기준을 밝혀요.","장단점을 써요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#1','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C3',1,'mc','auto','서로 다른 의견을 견주고 고쳐 모두가 받아들일 만한 의견을 찾는 일은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X14','K5-2-u4-X21']::text[],false,'{"seq":1,"concept":"K5-2-u4-C3","difficulty":1,"kind":"mc","stem":"서로 다른 의견을 견주고 고쳐 모두가 받아들일 만한 의견을 찾는 일은 어느 것인가요?","options":[{"t":"의견 조정","correct":true},{"t":"의견 버리기","mis":"K5-2-u4-X03"},{"t":"손들기","mis":"K5-2-u4-X14"},{"t":"맞장구","mis":"K5-2-u4-X21"}],"explanation":["버리지 않아요.","손들기와 달라요.","견주고 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#2','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C39',1,'mc','auto','「팩트 체크」를 순화어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":2,"concept":"K5-2-u4-C39","difficulty":1,"kind":"mc","stem":"「팩트 체크」를 순화어로 바꾸면 어느 것인가요?","options":[{"t":"사실 확인","correct":true},{"t":"개봉","mis":"K5-2-u4-X39"},{"t":"여행 안내원","mis":"K5-2-u4-X39"},{"t":"전시 기획자","mis":"K5-2-u4-X39"}],"explanation":["언박싱이에요.","여행 가이드예요.","사실을 확인한다는 뜻이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#3','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C9',1,'mc','auto','기준에 비추어 의견의 좋은 점과 아쉬운 점을 따지는 일은 어느 것인가요?',ARRAY['K5-2-u4-X23','K5-2-u4-X13','K5-2-u4-X35']::text[],false,'{"seq":3,"concept":"K5-2-u4-C9","difficulty":1,"kind":"mc","stem":"기준에 비추어 의견의 좋은 점과 아쉬운 점을 따지는 일은 어느 것인가요?","options":[{"t":"장점과 단점 검토하기","correct":true},{"t":"주제 정하기","mis":"K5-2-u4-X23"},{"t":"합의점 찾기","mis":"K5-2-u4-X13"},{"t":"되돌아보기","mis":"K5-2-u4-X35"}],"explanation":["맨 앞 절차예요.","그다음 차례예요.","장단점을 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#4','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C23',1,'mc','auto','학급 토의의 마지막 절차는 어느 것인가요?',ARRAY['K5-2-u4-X23']::text[],false,'{"seq":4,"concept":"K5-2-u4-C23","difficulty":1,"kind":"mc","stem":"학급 토의의 마지막 절차는 어느 것인가요?","options":[{"t":"의견 정하기","correct":true},{"t":"토의 주제 정하기","mis":"K5-2-u4-X23"},{"t":"의견 마련하기","mis":"K5-2-u4-X23"},{"t":"의견 나누기","mis":"K5-2-u4-X23"}],"explanation":["첫 절차예요.","둘째 절차예요.","실천할 의견을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#5','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C6',1,'mc','auto','준서가 제안한 의견은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X30']::text[],false,'{"seq":5,"concept":"K5-2-u4-C6","difficulty":1,"kind":"mc","stem":"준서가 제안한 의견은 어느 것인가요?","options":[{"t":"모둠마다 요일을 정하자","correct":true},{"t":"한 번에 네 명까지만 놀자","mis":"K5-2-u4-X06"},{"t":"놀이 자리와 규칙을 정하자","mis":"K5-2-u4-X06"},{"t":"블록 놀이를 없애자","mis":"K5-2-u4-X30"}],"explanation":["하윤이의 의견이에요.","나은이의 의견이에요.","준서는 요일을 제안했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#6','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C16',1,'mc','auto','토의 주제를 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C16","difficulty":1,"kind":"mc","stem":"토의 주제를 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리가 직접 풀 수 있는 문제인가?","correct":true},{"t":"가장 웃긴 문제인가?","mis":"K5-2-u4-X16"},{"t":"어른들만 풀 수 있는 문제인가?","mis":"K5-2-u4-X31"},{"t":"한 친구만 관심 있는 문제인가?","mis":"K5-2-u4-X16"}],"explanation":["재미가 기준이 아니에요.","우리가 도울 수 있어야 해요.","직접 풀 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#7','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C18',1,'mc','auto','공손한 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":7,"concept":"K5-2-u4-C18","difficulty":1,"kind":"mc","stem":"공손한 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「궁금해서 묻는데, 요일은 누가 정해?」","correct":true},{"t":"「그걸 의견이라고 냈어?」","mis":"K5-2-u4-X18"},{"t":"「넌 왜 맨날 그래?」","mis":"K5-2-u4-X18"},{"t":"「물어볼 것도 없어.」","mis":"K5-2-u4-X17"}],"explanation":["놀리는 말이에요.","탓하는 말이에요.","궁금한 점을 공손하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#8','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C30',1,'mc','auto','서로 다른 가치가 부딪칠 때 필요한 태도는 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31','K5-2-u4-X08']::text[],false,'{"seq":8,"concept":"K5-2-u4-C30","difficulty":1,"kind":"mc","stem":"서로 다른 가치가 부딪칠 때 필요한 태도는 어느 것인가요?","options":[{"t":"서로 존중하고 조금씩 양보하기","correct":true},{"t":"더 옳은 쪽만 이기게 하기","mis":"K5-2-u4-X30"},{"t":"모른 척하기","mis":"K5-2-u4-X31"},{"t":"큰 소리로 따지기","mis":"K5-2-u4-X08"}],"explanation":["겨루지 않아요.","모른 척하지 않아요.","존중하고 양보해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#9','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C6',2,'mc','auto','지안이가 제안한 의견은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X16']::text[],false,'{"seq":9,"concept":"K5-2-u4-C6","difficulty":2,"kind":"mc","stem":"지안이가 제안한 의견은 어느 것인가요?","options":[{"t":"물 주는 날을 적은 이름표를 꽂자","correct":true},{"t":"물 주는 당번을 정하자","mis":"K5-2-u4-X06"},{"t":"화분을 모두 창가로 옮기자","mis":"K5-2-u4-X06"},{"t":"화분을 집으로 가져가자","mis":"K5-2-u4-X16"}],"explanation":["태린이의 의견이에요.","로운이의 의견이에요.","지안이는 이름표를 제안했어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#10','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C9',2,'mc','auto','「모둠마다 요일을 정하자」 의견의 장점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X09','K5-2-u4-X04','K5-2-u4-X10']::text[],false,'{"seq":10,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"「모둠마다 요일을 정하자」 의견의 장점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 차례를 기다리며 양보하게 된다","correct":true},{"t":"특정 요일에 몰릴 수 있다","mis":"K5-2-u4-X09"},{"t":"블록이 늘어난다","mis":"K5-2-u4-X04"},{"t":"규칙이 필요 없다","mis":"K5-2-u4-X10"}],"explanation":["단점이에요.","관계없어요.","양보하게 돼요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#11','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C12',2,'mc','auto','합의점에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X08','K5-2-u4-X38']::text[],false,'{"seq":11,"concept":"K5-2-u4-C12","difficulty":2,"kind":"mc","stem":"합의점에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 의견을 만들거나 두 의견을 합칠 수도 있다","correct":true},{"t":"반드시 한 의견만 골라야 한다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 쪽으로 정한다","mis":"K5-2-u4-X08"},{"t":"정답이 처음부터 정해져 있다","mis":"K5-2-u4-X38"}],"explanation":["여러 모습이 있어요.","목소리로 정하지 않아요.","정답이 정해진 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#12','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C28',2,'mc','auto','반이 정당한 절차로 정한 의견이 내 의견과 다를 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X20','K5-2-u4-X37']::text[],false,'{"seq":12,"concept":"K5-2-u4-C28","difficulty":2,"kind":"mc","stem":"반이 정당한 절차로 정한 의견이 내 의견과 다를 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"받아들이고 함께 실천한다","correct":true},{"t":"내 의견대로만 한다","mis":"K5-2-u4-X28"},{"t":"다음 토의에는 나오지 않는다","mis":"K5-2-u4-X20"},{"t":"정한 친구들을 탓한다","mis":"K5-2-u4-X37"}],"explanation":["함께 정했어요.","참여는 소중해요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#13','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C39',2,'mc','auto','「북 트레일러」를 순화어로 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":13,"concept":"K5-2-u4-C39","difficulty":2,"kind":"mc","stem":"「북 트레일러」를 순화어로 바꾼 것은 어느 것인가요?","options":[{"t":"책 소개 영상","correct":true},{"t":"사실 확인","mis":"K5-2-u4-X39"},{"t":"여행 안내원","mis":"K5-2-u4-X39"},{"t":"개봉","mis":"K5-2-u4-X39"}],"explanation":["팩트 체크예요.","여행 가이드예요.","책을 소개하는 영상이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
