INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#15','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C8',2,'mc','auto','동네 공원 문제를 토의할 때 더하면 좋은 기준은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X16']::text[],false,'{"seq":15,"concept":"K5-2-u4-C8","difficulty":2,"kind":"mc","stem":"동네 공원 문제를 토의할 때 더하면 좋은 기준은 어느 것인가요?","options":[{"t":"비용이 많이 들지 않는가?","correct":true},{"t":"누가 제안했는가?","mis":"K5-2-u4-X08"},{"t":"목소리가 큰가?","mis":"K5-2-u4-X08"},{"t":"가장 웃긴가?","mis":"K5-2-u4-X16"}],"explanation":["사람이 기준이 아니에요.","목소리는 기준이 아니에요.","비용도 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#16','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C34',2,'mc','auto','학교 문제 토의 여섯 단계의 마지막은 어느 것인가요?',ARRAY['K5-2-u4-X35']::text[],false,'{"seq":16,"concept":"K5-2-u4-C34","difficulty":2,"kind":"mc","stem":"학교 문제 토의 여섯 단계의 마지막은 어느 것인가요?","options":[{"t":"되돌아보기","correct":true},{"t":"의견 정하기","mis":"K5-2-u4-X35"},{"t":"의견 모으기","mis":"K5-2-u4-X35"},{"t":"의견 나누기","mis":"K5-2-u4-X35"}],"explanation":["다섯째예요.","넷째예요.","마치고 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#17','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C38',3,'mc','auto','기록장의 합의점이 처음 의견들보다 나아진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X38','K5-2-u4-X08','K5-2-u4-X12']::text[],false,'{"seq":17,"concept":"K5-2-u4-C38","difficulty":3,"kind":"mc","stem":"기록장의 합의점이 처음 의견들보다 나아진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"질문하고 단점을 따지며 서로 보완했기 때문에","correct":true},{"t":"정답 의견을 맞혔기 때문에","mis":"K5-2-u4-X38"},{"t":"목소리 큰 친구가 정했기 때문에","mis":"K5-2-u4-X08"},{"t":"한 의견만 골랐기 때문에","mis":"K5-2-u4-X12"}],"explanation":["정답이 정해진 게 아니에요.","목소리로 정하지 않아요.","과정에서 나아졌어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#18','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C13',3,'mc','auto','블록 토의에서 합의점이 보이지 않아 기준을 다시 정하기로 했어요. 이에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X14','K5-2-u4-X01']::text[],false,'{"seq":18,"concept":"K5-2-u4-C13","difficulty":3,"kind":"mc","stem":"블록 토의에서 합의점이 보이지 않아 기준을 다시 정하기로 했어요. 이에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"필요하면 앞 차례로 되돌아가 다시 따질 수 있다","correct":true},{"t":"차례를 거꾸로 가면 토의가 틀린다","mis":"K5-2-u4-X13"},{"t":"바로 손을 들어 정해야 한다","mis":"K5-2-u4-X14"},{"t":"토의를 그만두어야 한다","mis":"K5-2-u4-X01"}],"explanation":["되돌아갈 수 있어요.","목적은 합의점이에요.","그만두지 않아요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#19','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C25',3,'mc','auto','학급 토의에서 의견이 많아 헷갈릴 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u4-X25','K5-2-u4-X08']::text[],false,'{"seq":19,"concept":"K5-2-u4-C25","difficulty":3,"kind":"mc","stem":"학급 토의에서 의견이 많아 헷갈릴 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"칠판에 의견과 기준, 장단점을 적어 한눈에 견준다","correct":true},{"t":"말로만 계속 주고받는다","mis":"K5-2-u4-X25"},{"t":"처음 의견으로 정한다","mis":"K5-2-u4-X08"},{"t":"목소리 큰 의견만 적는다","mis":"K5-2-u4-X08"}],"explanation":["정리가 안 돼요.","차례로 정하지 않아요.","한눈에 보이게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#20','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C32',3,'mc','auto','의견의 까닭을 더 타당하게 만드는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X32','K5-2-u4-X04','K5-2-u4-X11']::text[],false,'{"seq":20,"concept":"K5-2-u4-C32","difficulty":3,"kind":"mc","stem":"의견의 까닭을 더 타당하게 만드는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책이나 누리집에서 비슷한 사례를 찾아 덧붙인다","correct":true},{"t":"같은 말을 크게 되풀이한다","mis":"K5-2-u4-X32"},{"t":"까닭을 빼고 의견만 말한다","mis":"K5-2-u4-X04"},{"t":"다른 의견을 깎아내린다","mis":"K5-2-u4-X11"}],"explanation":["크게 말해도 근거가 안 돼요.","까닭이 필요해요.","자료로 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#21','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C10',3,'mc','auto','블록 토의에서 나은이 의견의 단점을 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X10']::text[],false,'{"seq":21,"concept":"K5-2-u4-C10","difficulty":3,"kind":"mc","stem":"블록 토의에서 나은이 의견의 단점을 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「규칙은 좋지만 꾸준히 지키게 하려면 살필 사람이 필요할 것 같아.」","correct":true},{"t":"「규칙 같은 건 아무도 안 지켜.」","mis":"K5-2-u4-X11"},{"t":"「나은이는 원래 그래.」","mis":"K5-2-u4-X11"},{"t":"「단점은 말하지 말자.」","mis":"K5-2-u4-X10"}],"explanation":["깎아내리는 말이에요.","사람을 두고 한 말이에요.","장점도 인정하고 의견을 두고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#22','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C5',3,'mc','auto','이 단원에서 배운 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X05']::text[],false,'{"seq":22,"concept":"K5-2-u4-C5","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"조정 방법 알기 → 모둠 토의 → 학급 토의 → 주변의 문제 → 학교 문제 실천","correct":true},{"t":"학교 문제 실천 → 모둠 토의 → 조정 방법 알기 → 학급 토의 → 주변의 문제","mis":"K5-2-u4-X05"},{"t":"학급 토의 → 주변의 문제 → 학교 문제 실천 → 조정 방법 알기 → 모둠 토의","mis":"K5-2-u4-X05"},{"t":"주변의 문제 → 조정 방법 알기 → 학교 문제 실천 → 학급 토의 → 모둠 토의","mis":"K5-2-u4-X05"}],"explanation":["실천은 맨 끝이에요.","방법이 먼저예요.","단원의 흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#23','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C23',4,'essay','teacher','학급 토의 절차 다섯 가지를 차례대로 쓰고, 그 가운데 「의견 모으기」에서 하는 일 세 가지를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C23","difficulty":4,"kind":"essay","stem":"학급 토의 절차 다섯 가지를 차례대로 쓰고, 그 가운데 「의견 모으기」에서 하는 일 세 가지를 쓰세요.","answer_guide":{"answer":"예: 토의 주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기. 의견 모으기에서는 의견을 검토할 기준 마련하기, 의견의 장점과 단점 검토하기, 합의점 찾기를 한다.","scoring_points":["다섯 절차를 차례대로 썼는가","의견 모으기의 세 가지를 썼는가","차례가 알맞은가"]},"explanation":["다섯 절차예요.","세 가지예요.","차례를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#24','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C28',4,'essay','teacher','학급에서 정한 의견이 내 의견과 다를 때 어떻게 할지 까닭과 함께 쓰고, 실천해 보니 잘되지 않으면 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C28","difficulty":4,"kind":"essay","stem":"학급에서 정한 의견이 내 의견과 다를 때 어떻게 할지 까닭과 함께 쓰고, 실천해 보니 잘되지 않으면 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 정당한 절차로 반 전체가 정한 의견이므로 내 의견과 달라도 받아들이고 함께 실천하겠다. 모두가 지켜야 문제가 풀리기 때문이다. 해 보니 잘되지 않으면 실천한 모습을 나누고 다시 토의하자고 하겠다.","scoring_points":["받아들이고 실천한다고 썼는가","까닭을 썼는가","다시 토의할 수 있음을 썼는가"]},"explanation":["받아들여요.","까닭을 써요.","다시 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#25','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C37',4,'essay','teacher','이 단원에서 한 토의 가운데 하나를 떠올려 잘한 점과 보완할 점을 쓰고, 앞으로 토의에서 지킬 다짐을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C37","difficulty":4,"kind":"essay","stem":"이 단원에서 한 토의 가운데 하나를 떠올려 잘한 점과 보완할 점을 쓰고, 앞으로 토의에서 지킬 다짐을 쓰세요.","answer_guide":{"answer":"예: 학급 토의에서 기준을 먼저 정해 차분히 따진 점이 좋았다. 다만 몇몇 친구만 말하고 조용한 친구의 의견을 다 듣지 못한 점은 보완해야 한다. 앞으로는 친구 의견에 공손하게 질문하고, 모두 한 번씩 말할 수 있게 기다리겠다.","scoring_points":["잘한 점을 썼는가","보완할 점을 탓하지 않고 썼는가","다짐을 썼는가"]},"explanation":["잘한 점이에요.","보완할 점이에요.","다짐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#1','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C2',1,'ox','auto','토의는 누가 이기는지 겨루는 말하기예요.',ARRAY['K5-2-u4-X02']::text[],false,'{"seq":1,"concept":"K5-2-u4-C2","difficulty":1,"kind":"ox","stem":"토의는 누가 이기는지 겨루는 말하기예요.","answer":"X","reason_options":[{"t":"여럿이 함께 더 나은 방법을 찾는 말하기이기 때문에","correct":true},{"t":"말을 잘하는 사람이 정답을 가리는 자리이기 때문에","mis":"K5-2-u4-X02"}],"mis":"K5-2-u4-X02","explanation":["겨루지 않아요.","함께 찾아요.","토의의 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#2','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C39',1,'mc','auto','「언박싱」을 순화어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":2,"concept":"K5-2-u4-C39","difficulty":1,"kind":"mc","stem":"「언박싱」을 순화어로 바꾸면 어느 것인가요?","options":[{"t":"개봉","correct":true},{"t":"사실 확인","mis":"K5-2-u4-X39"},{"t":"책 소개 영상","mis":"K5-2-u4-X39"},{"t":"여행 안내원","mis":"K5-2-u4-X39"}],"explanation":["팩트 체크예요.","북 트레일러예요.","상자를 연다는 뜻이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#3','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C11',1,'mc','auto','서로 조금씩 양보해 의견이 하나로 모이는 자리는 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X07','K5-2-u4-X10']::text[],false,'{"seq":3,"concept":"K5-2-u4-C11","difficulty":1,"kind":"mc","stem":"서로 조금씩 양보해 의견이 하나로 모이는 자리는 어느 것인가요?","options":[{"t":"합의점","correct":true},{"t":"출발점","mis":"K5-2-u4-X11"},{"t":"기준","mis":"K5-2-u4-X07"},{"t":"단점","mis":"K5-2-u4-X10"}],"explanation":["처음 자리예요.","견주는 잣대예요.","모이는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#4','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C24',1,'mc','auto','기준을 정하고 장단점을 따져 합의점을 찾는 학급 토의 절차는 어느 것인가요?',ARRAY['K5-2-u4-X24']::text[],false,'{"seq":4,"concept":"K5-2-u4-C24","difficulty":1,"kind":"mc","stem":"기준을 정하고 장단점을 따져 합의점을 찾는 학급 토의 절차는 어느 것인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"의견 마련하기","mis":"K5-2-u4-X24"},{"t":"의견 나누기","mis":"K5-2-u4-X24"},{"t":"토의 주제 정하기","mis":"K5-2-u4-X24"}],"explanation":["각자 쓰는 절차예요.","발표하는 절차예요.","조정은 의견 모으기 안에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#5','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C4',1,'mc','auto','하윤이가 든 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X04']::text[],false,'{"seq":5,"concept":"K5-2-u4-C4","difficulty":1,"kind":"mc","stem":"하윤이가 든 까닭은 어느 것인가요?","options":[{"t":"자리가 넉넉해지고 소리도 줄어서","correct":true},{"t":"서로 차례를 기다리며 양보해서","mis":"K5-2-u4-X06"},{"t":"작은 목소리로 놀 수 있어서","mis":"K5-2-u4-X06"},{"t":"블록이 많아져서","mis":"K5-2-u4-X04"}],"explanation":["준서의 까닭이에요.","나은이의 까닭이에요.","하윤이는 자리와 소리를 들었어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#6','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C15',1,'mc','auto','「어떻게 하면 ~할까?」 꼴로 토의 주제를 정하는 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X16','K5-2-u4-X38']::text[],false,'{"seq":6,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"「어떻게 하면 ~할까?」 꼴로 토의 주제를 정하는 까닭은 어느 것인가요?","options":[{"t":"함께 방법을 찾는 물음이 되어서","correct":true},{"t":"누구 탓인지 알 수 있어서","mis":"K5-2-u4-X15"},{"t":"글자가 짧아서","mis":"K5-2-u4-X16"},{"t":"정답이 하나로 정해져서","mis":"K5-2-u4-X38"}],"explanation":["탓하지 않아요.","길이는 관계없어요.","방법을 찾는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#7','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C20',1,'ox','auto','내 의견이 뽑히지 않아도 토의에 참여한 것은 소중해요.',ARRAY['K5-2-u4-X20']::text[],false,'{"seq":7,"concept":"K5-2-u4-C20","difficulty":1,"kind":"ox","stem":"내 의견이 뽑히지 않아도 토의에 참여한 것은 소중해요.","answer":"O","reason_options":[{"t":"함께 말하고 고친 과정 속에 내 생각도 들어 있기 때문에","correct":true},{"t":"뽑히지 않은 의견은 아무 쓸모가 없기 때문에","mis":"K5-2-u4-X20"}],"mis":"K5-2-u4-X20","explanation":["참여가 소중해요.","내 생각도 들어 있어요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#8','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C29',1,'ox','auto','놀이터에서 공을 차는 아이들과 쉬고 싶은 이웃은 서로 소중히 여기는 것이 달라요.',ARRAY['K5-2-u4-X29']::text[],false,'{"seq":8,"concept":"K5-2-u4-C29","difficulty":1,"kind":"ox","stem":"놀이터에서 공을 차는 아이들과 쉬고 싶은 이웃은 서로 소중히 여기는 것이 달라요.","answer":"O","reason_options":[{"t":"아이들은 즐겁게 노는 것을, 이웃은 조용한 저녁을 소중히 여기기 때문에","correct":true},{"t":"한쪽이 잘못했기 때문에","mis":"K5-2-u4-X29"}],"mis":"K5-2-u4-X29","explanation":["둘 다 바라는 것이 있어요.","잘못이 아니라 가치가 달라요.","바르게 말했어요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#9','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C9',2,'mc','auto','기록장에 나온 로운 의견의 단점은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X09']::text[],false,'{"seq":9,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"기록장에 나온 로운 의견의 단점은 어느 것인가요?","options":[{"t":"창가가 좁아 화분이 다 들어가지 않는다","correct":true},{"t":"햇빛을 받으면 덜 시든다","mis":"K5-2-u4-X10"},{"t":"날마다 잊지 않고 챙긴다","mis":"K5-2-u4-X09"},{"t":"단점이 없다","mis":"K5-2-u4-X10"}],"explanation":["장점이에요.","태린이 의견의 장점이에요.","기록장에 단점이 있어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#10','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C10',2,'error','auto','블록 토의에서 단점을 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X09','K5-2-u4-X10']::text[],false,'{"seq":10,"concept":"K5-2-u4-C10","difficulty":2,"kind":"error","stem":"블록 토의에서 단점을 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「나은이는 늘 규칙만 좋아하니까 이번에도 별로야.」","correct":true,"mis_target":"K5-2-u4-X11"},{"t":"「규칙은 좋지만 꾸준히 지키는지 살피기가 어려울 것 같아.」","mis":"K5-2-u4-X09"},{"t":"「요일을 정하면 어떤 날에 몰릴 수 있을 것 같아.」","mis":"K5-2-u4-X10"}],"explanation":["의견을 두고 말했어요.","의견을 두고 말했어요.","사람이 아니라 의견을 두고 말해요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#11','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C11',2,'mc','auto','기록장의 합의점이 이름표 의견을 「코팅한 이름표」로 고친 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X20','K5-2-u4-X17']::text[],false,'{"seq":11,"concept":"K5-2-u4-C11","difficulty":2,"kind":"mc","stem":"기록장의 합의점이 이름표 의견을 「코팅한 이름표」로 고친 까닭은 어느 것인가요?","options":[{"t":"젖거나 떨어질 수 있다는 단점을 보완하려고","correct":true},{"t":"이름표 의견을 버리려고","mis":"K5-2-u4-X03"},{"t":"지안이가 토의에서 졌기 때문에","mis":"K5-2-u4-X20"},{"t":"질문을 무시하려고","mis":"K5-2-u4-X17"}],"explanation":["살렸어요.","진 것이 아니에요.","질문으로 찾은 단점을 메웠어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#12','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C28',2,'mc','auto','반이 정한 의견을 실천해 보니 잘 안 될 때 할 수 있는 일은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X37','K5-2-u4-X14']::text[],false,'{"seq":12,"concept":"K5-2-u4-C28","difficulty":2,"kind":"mc","stem":"반이 정한 의견을 실천해 보니 잘 안 될 때 할 수 있는 일은 어느 것인가요?","options":[{"t":"실천한 모습을 나누고 다시 토의한다","correct":true},{"t":"한 번 정했으니 그대로 둔다","mis":"K5-2-u4-X28"},{"t":"누구 잘못인지 따진다","mis":"K5-2-u4-X37"},{"t":"토의는 쓸모없다고 여긴다","mis":"K5-2-u4-X14"}],"explanation":["다시 고칠 수 있어요.","탓하지 않아요.","다시 토의해 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#13','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C39',2,'mc','auto','「할머니도 알아들으시게 「개봉」이라고 쓰자.」라는 말에 담긴 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":13,"concept":"K5-2-u4-C39","difficulty":2,"kind":"mc","stem":"「할머니도 알아들으시게 「개봉」이라고 쓰자.」라는 말에 담긴 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 서로 통하기 위한 것이라 누구나 알기 쉬워야 한다","correct":true},{"t":"외래어를 쓰면 더 멋지다","mis":"K5-2-u4-X39"},{"t":"순화어는 장난으로 만든 말이다","mis":"K5-2-u4-X39"},{"t":"어려운 말일수록 좋은 말이다","mis":"K5-2-u4-X39"}],"explanation":["알기 쉬운 게 중요해요.","장난이 아니에요.","누구나 알아듣게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#14','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C36',2,'mc','auto','「창가로 모두 옮기자」에서 「해가 필요한 화분만 옮기자」로 바꾼 것은 어떤 생각 도구에 가까운가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":14,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"「창가로 모두 옮기자」에서 「해가 필요한 화분만 옮기자」로 바꾼 것은 어떤 생각 도구에 가까운가요?","options":[{"t":"줄이기 · 빼기","correct":true},{"t":"합치기","mis":"K5-2-u4-X36"},{"t":"순서 바꾸기","mis":"K5-2-u4-X36"},{"t":"포기하기","mis":"K5-2-u4-X36"}],"explanation":["두 의견을 붙인 게 아니에요.","차례를 바꾼 게 아니에요.","일부만 옮기도록 줄였어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#15','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C7',2,'mc','auto','기준을 먼저 정하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X07','K5-2-u4-X08','K5-2-u4-X21']::text[],false,'{"seq":15,"concept":"K5-2-u4-C7","difficulty":2,"kind":"mc","stem":"기준을 먼저 정하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 의견을 같은 잣대로 견줄 수 있어서","correct":true},{"t":"마음에 드는 의견을 빨리 고르려고","mis":"K5-2-u4-X07"},{"t":"목소리 큰 친구를 따르려고","mis":"K5-2-u4-X08"},{"t":"토의를 길게 하려고","mis":"K5-2-u4-X21"}],"explanation":["따지지 않게 돼요.","목소리로 정하지 않아요.","같은 잣대로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#16','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C35',2,'mc','auto','의견을 정한 뒤 이견이 없는지 확인하는 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X34','K5-2-u4-X38']::text[],false,'{"seq":16,"concept":"K5-2-u4-C35","difficulty":2,"kind":"mc","stem":"의견을 정한 뒤 이견이 없는지 확인하는 까닭은 어느 것인가요?","options":[{"t":"모두가 받아들여야 함께 실천할 수 있어서","correct":true},{"t":"먼저 말한 친구를 정하려고","mis":"K5-2-u4-X08"},{"t":"이견이 있어도 상관없어서","mis":"K5-2-u4-X34"},{"t":"선생님 의견을 따르려고","mis":"K5-2-u4-X38"}],"explanation":["차례는 관계없어요.","확인해야 해요.","함께 실천하려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#17','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C7',3,'mc','auto','로운 의견을 「실천할 수 있는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X07','K5-2-u4-X11']::text[],false,'{"seq":17,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"로운 의견을 「실천할 수 있는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"창가가 좁아 화분을 모두 옮기기 어렵다","correct":true},{"t":"로운이가 말했으니 실천할 수 있다","mis":"K5-2-u4-X08"},{"t":"햇빛이 좋으니 따질 필요 없다","mis":"K5-2-u4-X07"},{"t":"기준으로 따지면 로운이가 속상하다","mis":"K5-2-u4-X11"}],"explanation":["말한 사람이 기준이 아니에요.","기준으로 따져요.","실천할 수 있는지 봐요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#18','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C21',3,'mc','auto','블록 토의에서 모두 「좋아.」라고만 했다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X10','K5-2-u4-X17']::text[],false,'{"seq":18,"concept":"K5-2-u4-C21","difficulty":3,"kind":"mc","stem":"블록 토의에서 모두 「좋아.」라고만 했다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"특정 요일에 몰리는 문제를 미리 찾지 못한다","correct":true},{"t":"토의가 더 나아진다","mis":"K5-2-u4-X21"},{"t":"단점이 저절로 사라진다","mis":"K5-2-u4-X10"},{"t":"모두가 질문을 많이 한다","mis":"K5-2-u4-X17"}],"explanation":["따지지 않으면 못 찾아요.","단점은 남아 있어요.","질문하지 않게 돼요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#19','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C22',3,'mc','auto','학급 토의 사회자가 하는 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X22','K5-2-u4-X25','K5-2-u4-X26']::text[],false,'{"seq":19,"concept":"K5-2-u4-C22","difficulty":3,"kind":"mc","stem":"학급 토의 사회자가 하는 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"자기 마음에 드는 의견으로 정해 버리기","correct":true},{"t":"절차 안내하기","mis":"K5-2-u4-X22"},{"t":"의견 정리하기","mis":"K5-2-u4-X25"},{"t":"여러 친구가 말하게 돕기","mis":"K5-2-u4-X26"}],"explanation":["사회자의 일이에요.","사회자의 일이에요.","대신 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#20','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C33',3,'mc','auto','주변의 문제로 정한 의견을 알릴 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X33','K5-2-u4-X31','K5-2-u4-X15']::text[],false,'{"seq":20,"concept":"K5-2-u4-C33","difficulty":3,"kind":"mc","stem":"주변의 문제로 정한 의견을 알릴 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"관리하는 곳에 의견과 까닭을 담은 제안 편지를 보낸다","correct":true},{"t":"「알린다」고만 적는다","mis":"K5-2-u4-X33"},{"t":"우리끼리만 기억한다","mis":"K5-2-u4-X31"},{"t":"불평하는 쪽지를 붙인다","mis":"K5-2-u4-X15"}],"explanation":["누구에게 어떻게가 빠졌어요.","알려야 바뀌어요.","알맞은 곳에 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#21','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C17',3,'mc','auto','질문하며 들으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17','K5-2-u4-X20']::text[],false,'{"seq":21,"concept":"K5-2-u4-C17","difficulty":3,"kind":"mc","stem":"질문하며 들으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의견이 또렷해지고 빈틈을 보완할 수 있다","correct":true},{"t":"친구 의견을 빨리 떨어뜨릴 수 있다","mis":"K5-2-u4-X18"},{"t":"토의 시간이 늘 짧아진다","mis":"K5-2-u4-X17"},{"t":"내 의견만 뽑히게 된다","mis":"K5-2-u4-X20"}],"explanation":["떨어뜨리려는 게 아니에요.","시간이 목적이 아니에요.","함께 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#22','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C14',3,'mc','auto','「끝내 손을 들어 정했으니 토의는 헛수고였다.」는 말에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X14','K5-2-u4-X01']::text[],false,'{"seq":22,"concept":"K5-2-u4-C14","difficulty":3,"kind":"mc","stem":"「끝내 손을 들어 정했으니 토의는 헛수고였다.」는 말에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장단점을 따진 과정 덕분에 모두 의견을 잘 알고 정할 수 있었다","correct":true},{"t":"맞아, 처음부터 손을 들었어야 했다","mis":"K5-2-u4-X14"},{"t":"적은 쪽의 생각은 틀렸다","mis":"K5-2-u4-X01"},{"t":"토의는 앞으로 하지 말아야 한다","mis":"K5-2-u4-X14"}],"explanation":["목적은 합의점이에요.","틀린 생각이 아니에요.","과정이 쓸모 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#23','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C39',4,'essay','teacher','외래어 하나를 골라 순화어로 바꾸어 쓰고, 순화어를 쓰면 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C39","difficulty":4,"kind":"essay","stem":"외래어 하나를 골라 순화어로 바꾸어 쓰고, 순화어를 쓰면 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 「여행 가이드」를 「여행 안내원」으로 바꾼다. 순화어를 쓰면 할머니 할아버지처럼 외래어가 낯선 사람도 쉽게 알아들을 수 있고, 우리말을 아끼고 지키는 데에도 도움이 된다.","scoring_points":["외래어를 순화어로 바르게 바꾸었는가","좋은 점 두 가지를 썼는가","말은 서로 통하기 위한 것임이 드러나는가"]},"explanation":["바르게 바꿔요.","좋은 점 두 가지예요.","누구나 알기 쉬워요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#24','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C36',4,'essay','teacher','맞선 두 의견을 하나 떠올리고, 생각 도구 물음 가운데 둘을 써서 새 의견을 두 가지 만들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C36","difficulty":4,"kind":"essay","stem":"맞선 두 의견을 하나 떠올리고, 생각 도구 물음 가운데 둘을 써서 새 의견을 두 가지 만들어 쓰세요.","answer_guide":{"answer":"예: 「점심시간에 공놀이를 하자」와 「교실에서 그림 그리기를 하자」 — 순서 바꾸기로 요일마다 번갈아 하고, 합치기로 그림 그리기 대회 뒤에 공놀이 시간을 이어 붙인다.","scoring_points":["맞선 두 의견을 썼는가","생각 도구 둘을 밝혔는가","새 의견 두 가지를 썼는가"]},"explanation":["맞선 의견이에요.","도구 둘이에요.","새 의견 둘이에요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_c#25','kor',5,2,'u4','','g5_2_kor_u4_review_c','unit_review','K5-2-u4-C2',4,'essay','teacher','토의와 의견 조정의 뜻을 쓰고, 토의에서 의견을 조정하면 좋은 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C2","difficulty":4,"kind":"essay","stem":"토의와 의견 조정의 뜻을 쓰고, 토의에서 의견을 조정하면 좋은 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 토의는 여럿이 함께 문제를 풀 방법을 찾는 말하기이고, 의견 조정은 서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일이다. 의견을 조정하면 여러 의견의 장점을 살려 더 나은 방법을 찾을 수 있고, 모두가 받아들여 함께 실천하기 쉽다.","scoring_points":["토의의 뜻을 썼는가","의견 조정의 뜻을 썼는가","좋은 점 두 가지를 썼는가"]},"explanation":["토의의 뜻이에요.","조정의 뜻이에요.","좋은 점 두 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#1','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C3',1,'ox','auto','의견을 조정하면 내 의견을 모두 버려야 해요.',ARRAY['K5-2-u4-X03']::text[],false,'{"seq":1,"concept":"K5-2-u4-C3","difficulty":1,"kind":"ox","stem":"의견을 조정하면 내 의견을 모두 버려야 해요.","answer":"X","reason_options":[{"t":"장점은 살리고 단점은 보완해 더 나은 의견으로 고치는 것이기 때문에","correct":true},{"t":"다른 사람 의견을 따르려면 내 생각은 없어야 하기 때문에","mis":"K5-2-u4-X03"}],"mis":"K5-2-u4-X03","explanation":["버리지 않아요.","내 생각도 들어가요.","살리고 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#2','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C39',1,'ox','auto','「큐레이터」는 「전시 기획자」로 바꾸어 쓸 수 있어요.',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":2,"concept":"K5-2-u4-C39","difficulty":1,"kind":"ox","stem":"「큐레이터」는 「전시 기획자」로 바꾸어 쓸 수 있어요.","answer":"O","reason_options":[{"t":"누구나 알기 쉬운 우리말로 다듬은 순화어이기 때문에","correct":true},{"t":"외래어는 무조건 쓰면 안 되기 때문에","mis":"K5-2-u4-X39"}],"mis":"K5-2-u4-X39","explanation":["짝이 맞아요.","쉬운 말로 다듬었어요.","순화어예요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#3','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C13',1,'ox','auto','의견을 조정하다 막히면 앞 차례로 되돌아가 다시 따져 볼 수 있어요.',ARRAY['K5-2-u4-X13']::text[],false,'{"seq":3,"concept":"K5-2-u4-C13","difficulty":1,"kind":"ox","stem":"의견을 조정하다 막히면 앞 차례로 되돌아가 다시 따져 볼 수 있어요.","answer":"O","reason_options":[{"t":"조정 차례는 고정된 길이 아니라 필요하면 오가며 하기 때문에","correct":true},{"t":"한 번 지난 차례로는 돌아갈 수 없기 때문에","mis":"K5-2-u4-X13"}],"mis":"K5-2-u4-X13","explanation":["오갈 수 있어요.","되돌아가도 돼요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#4','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C23',1,'blank','auto','학급 토의 절차 「주제 정하기 → 의견 마련하기 → ( ? ) → 의견 모으기 → 의견 정하기」의 빈칸에 들어갈 말은 어느 것인가요?',ARRAY['K5-2-u4-X35','K5-2-u4-X24','K5-2-u4-X14']::text[],false,'{"seq":4,"concept":"K5-2-u4-C23","difficulty":1,"kind":"blank","stem":"학급 토의 절차 「주제 정하기 → 의견 마련하기 → ( ? ) → 의견 모으기 → 의견 정하기」의 빈칸에 들어갈 말은 어느 것인가요?","options":[{"t":"의견 나누기","correct":true},{"t":"되돌아보기","mis":"K5-2-u4-X35"},{"t":"합의점 찾기","mis":"K5-2-u4-X24"},{"t":"손들기","mis":"K5-2-u4-X14"}],"explanation":["여섯째 단계예요.","의견 모으기 안에 있어요.","마련한 의견을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#5','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C22',1,'mc','auto','토의 「블록 놀이 자리」에서 사회자가 한 일은 어느 것인가요?',ARRAY['K5-2-u4-X22','K5-2-u4-X26','K5-2-u4-X18']::text[],false,'{"seq":5,"concept":"K5-2-u4-C22","difficulty":1,"kind":"mc","stem":"토의 「블록 놀이 자리」에서 사회자가 한 일은 어느 것인가요?","options":[{"t":"풀어야 할 문제를 밝히고 방법을 말해 보자고 안내했다","correct":true},{"t":"자기 의견으로 정해 버렸다","mis":"K5-2-u4-X22"},{"t":"한 친구만 말하게 했다","mis":"K5-2-u4-X26"},{"t":"하윤이의 의견을 놀렸다","mis":"K5-2-u4-X18"}],"explanation":["대신 정하지 않아요.","여러 친구가 말했어요.","문제를 밝히고 안내했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#6','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C16',1,'ox','auto','토의 주제는 우리와 관련이 있고 가장 먼저 풀어야 할 문제로 골라요.',ARRAY['K5-2-u4-X16']::text[],false,'{"seq":6,"concept":"K5-2-u4-C16","difficulty":1,"kind":"ox","stem":"토의 주제는 우리와 관련이 있고 가장 먼저 풀어야 할 문제로 골라요.","answer":"O","reason_options":[{"t":"우리가 함께 풀 필요가 있고 급한 문제부터 풀어야 하기 때문에","correct":true},{"t":"가장 재미있게 들리는 문제를 골라야 하기 때문에","mis":"K5-2-u4-X16"}],"mis":"K5-2-u4-X16","explanation":["관련이 있어야 해요.","급한 것부터예요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#7','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C26',1,'ox','auto','학급 토의에서는 몇몇 친구만 말해도 괜찮아요.',ARRAY['K5-2-u4-X26']::text[],false,'{"seq":7,"concept":"K5-2-u4-C26","difficulty":1,"kind":"ox","stem":"학급 토의에서는 몇몇 친구만 말해도 괜찮아요.","answer":"X","reason_options":[{"t":"반 전체의 문제라 모두가 의견을 마련하고 참여해야 하기 때문에","correct":true},{"t":"말 잘하는 친구의 의견이 늘 가장 좋기 때문에","mis":"K5-2-u4-X26"}],"mis":"K5-2-u4-X26","explanation":["모두의 문제예요.","모두 참여해요.","여러 친구가 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#8','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C31',1,'ox','auto','주변의 문제도 우리가 토의해 풀이에 도움을 줄 수 있어요.',ARRAY['K5-2-u4-X31']::text[],false,'{"seq":8,"concept":"K5-2-u4-C31","difficulty":1,"kind":"ox","stem":"주변의 문제도 우리가 토의해 풀이에 도움을 줄 수 있어요.","answer":"O","reason_options":[{"t":"의견을 모아 알맞은 곳에 제안할 수 있기 때문에","correct":true},{"t":"어른들만 풀 수 있는 문제이기 때문에","mis":"K5-2-u4-X31"}],"mis":"K5-2-u4-X31","explanation":["우리도 도울 수 있어요.","제안할 수 있어요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#9','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C17',2,'mc','auto','기록장의 질문은 어떤 의견의 빈틈을 채우려고 한 것인가요?',ARRAY['K5-2-u4-X17','K5-2-u4-X15']::text[],false,'{"seq":9,"concept":"K5-2-u4-C17","difficulty":2,"kind":"mc","stem":"기록장의 질문은 어떤 의견의 빈틈을 채우려고 한 것인가요?","options":[{"t":"지안이의 이름표 의견","correct":true},{"t":"태린이의 당번 의견","mis":"K5-2-u4-X17"},{"t":"로운이의 창가 의견","mis":"K5-2-u4-X17"},{"t":"사회자의 주제","mis":"K5-2-u4-X15"}],"explanation":["이름표에 대한 질문이에요.","이름표에 대한 질문이에요.","이름표가 젖거나 떨어질 때를 물었어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#10','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C10',2,'ox','auto','단점을 말하는 것은 더 나은 의견을 찾기 위한 과정이에요.',ARRAY['K5-2-u4-X11']::text[],false,'{"seq":10,"concept":"K5-2-u4-C10","difficulty":2,"kind":"ox","stem":"단점을 말하는 것은 더 나은 의견을 찾기 위한 과정이에요.","answer":"O","reason_options":[{"t":"단점을 알아야 보완해 최선의 의견을 찾을 수 있기 때문에","correct":true},{"t":"친구의 의견을 떨어뜨려야 내 의견이 뽑히기 때문에","mis":"K5-2-u4-X11"}],"mis":"K5-2-u4-X11","explanation":["비난이 아니에요.","보완하려고 따져요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#11','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C12',2,'ox','auto','합의점을 찾을 때 두 가지 이상의 의견을 함께 고를 수도 있어요.',ARRAY['K5-2-u4-X12']::text[],false,'{"seq":11,"concept":"K5-2-u4-C12","difficulty":2,"kind":"ox","stem":"합의점을 찾을 때 두 가지 이상의 의견을 함께 고를 수도 있어요.","answer":"O","reason_options":[{"t":"여러 의견의 장점을 살리는 것도 합의이기 때문에","correct":true},{"t":"합의점은 반드시 하나의 의견이어야 하기 때문에","mis":"K5-2-u4-X12"}],"mis":"K5-2-u4-X12","explanation":["함께 고를 수 있어요.","여러 모습이에요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#12','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C27',2,'ox','auto','토의에서는 적은 사람의 의견이라도 까닭이 옳으면 따를 수 있어요.',ARRAY['K5-2-u4-X27']::text[],false,'{"seq":12,"concept":"K5-2-u4-C27","difficulty":2,"kind":"ox","stem":"토의에서는 적은 사람의 의견이라도 까닭이 옳으면 따를 수 있어요.","answer":"O","reason_options":[{"t":"토의는 숫자보다 의견을 조정해 합의하는 방법이기 때문에","correct":true},{"t":"토의도 늘 많은 쪽으로만 정하기 때문에","mis":"K5-2-u4-X27"}],"mis":"K5-2-u4-X27","explanation":["까닭이 옳으면 따라요.","조정해 정해요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#13','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C39',2,'ox','auto','순화어를 쓰면 여러 세대가 함께 알아듣기 쉬워요.',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":13,"concept":"K5-2-u4-C39","difficulty":2,"kind":"ox","stem":"순화어를 쓰면 여러 세대가 함께 알아듣기 쉬워요.","answer":"O","reason_options":[{"t":"어려운 외래어를 누구나 아는 쉬운 우리말로 바꾸었기 때문에","correct":true},{"t":"순화어는 또래끼리만 쓰는 말이기 때문에","mis":"K5-2-u4-X39"}],"mis":"K5-2-u4-X39","explanation":["누구나 알아들어요.","쉬운 우리말이에요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#14','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C36',2,'ox','auto','합의점이 막히면 생각 도구 물음을 던져 새 의견을 떠올릴 수 있어요.',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":14,"concept":"K5-2-u4-C36","difficulty":2,"kind":"ox","stem":"합의점이 막히면 생각 도구 물음을 던져 새 의견을 떠올릴 수 있어요.","answer":"O","reason_options":[{"t":"바꾸기 · 합치기 · 빼기 · 순서 바꾸기 물음이 막힌 생각을 풀어 주기 때문에","correct":true},{"t":"막히면 토의를 그만두어야 하기 때문에","mis":"K5-2-u4-X36"}],"mis":"K5-2-u4-X36","explanation":["물음을 던져요.","포기하지 않아요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#15','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C8',2,'ox','auto','검토 기준은 어떤 문제든 늘 똑같은 세 가지로만 정해야 해요.',ARRAY['K5-2-u4-X09']::text[],false,'{"seq":15,"concept":"K5-2-u4-C8","difficulty":2,"kind":"ox","stem":"검토 기준은 어떤 문제든 늘 똑같은 세 가지로만 정해야 해요.","answer":"X","reason_options":[{"t":"문제에 따라 기준을 다르게 정하거나 새로 더할 수 있기 때문에","correct":true},{"t":"기준이 바뀌면 토의가 틀리기 때문에","mis":"K5-2-u4-X09"}],"mis":"K5-2-u4-X09","explanation":["문제마다 달라요.","더할 수 있어요.","비용 같은 기준도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#16','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C37',2,'ox','auto','되돌아보기는 잘한 점과 다음에 함께 노력할 점을 찾는 시간이에요.',ARRAY['K5-2-u4-X37']::text[],false,'{"seq":16,"concept":"K5-2-u4-C37","difficulty":2,"kind":"ox","stem":"되돌아보기는 잘한 점과 다음에 함께 노력할 점을 찾는 시간이에요.","answer":"O","reason_options":[{"t":"누구 잘못인지 따지기보다 다음 토의를 더 잘하려고 하기 때문에","correct":true},{"t":"잘못한 친구를 찾는 시간이기 때문에","mis":"K5-2-u4-X37"}],"mis":"K5-2-u4-X37","explanation":["탓하지 않아요.","다음을 준비해요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#17','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C17',3,'error','auto','기록장을 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X17','K5-2-u4-X36']::text[],false,'{"seq":17,"concept":"K5-2-u4-C17","difficulty":3,"kind":"error","stem":"기록장을 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「질문 때문에 시간만 오래 걸렸으니 묻지 말걸.」","correct":true,"mis_target":"K5-2-u4-X17"},{"t":"「질문 덕분에 코팅한 이름표로 고쳤어.」","mis":"K5-2-u4-X17"},{"t":"「로운이 의견도 해가 필요한 화분으로 줄여 살렸어.」","mis":"K5-2-u4-X36"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","질문이 의견을 단단하게 했어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#18','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C19',3,'error','auto','블록 토의 모둠 의견을 고치는 말이에요. 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X19','K5-2-u4-X12']::text[],false,'{"seq":18,"concept":"K5-2-u4-C19","difficulty":3,"kind":"error","stem":"블록 토의 모둠 의견을 고치는 말이에요. 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「단점이 있는 의견은 다 지우고 남는 것만 하자.」","correct":true,"mis_target":"K5-2-u4-X10"},{"t":"「요일 의견은 몰리지 않게 모둠을 고루 나누어 살리자.」","mis":"K5-2-u4-X19"},{"t":"「인원 의견과 규칙 의견을 합쳐 보자.」","mis":"K5-2-u4-X12"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","단점은 보완할 거리예요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#19','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C28',3,'error','auto','학급에서 정한 의견을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X20','K5-2-u4-X13']::text[],false,'{"seq":19,"concept":"K5-2-u4-C28","difficulty":3,"kind":"error","stem":"학급에서 정한 의견을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「내 의견이 아니었으니 나는 안 지킬래.」","correct":true,"mis_target":"K5-2-u4-X28"},{"t":"「내 생각과 달랐지만 함께 정했으니 해 볼게.」","mis":"K5-2-u4-X20"},{"t":"「해 보고 문제가 있으면 다시 토의하자.」","mis":"K5-2-u4-X13"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","함께 정한 것은 함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#20','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C29',3,'error','auto','주변의 부딪침을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X29','K5-2-u4-X30']::text[],false,'{"seq":20,"concept":"K5-2-u4-C29","difficulty":3,"kind":"error","stem":"주변의 부딪침을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「공원에서 자전거 타는 사람은 다 이기적이야.」","correct":true,"mis_target":"K5-2-u4-X29"},{"t":"「자전거 타는 사람은 시원하게 달리고 싶은 거야.」","mis":"K5-2-u4-X29"},{"t":"「걷는 사람은 마음 놓고 걷고 싶은 거야.」","mis":"K5-2-u4-X30"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","나쁜 사람이 아니라 가치가 달라요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#21','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C21',3,'error','auto','모둠 토의 장면을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X17']::text[],false,'{"seq":21,"concept":"K5-2-u4-C21","difficulty":3,"kind":"error","stem":"모둠 토의 장면을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「다들 좋다고만 하니 이 토의는 완벽해.」","correct":true,"mis_target":"K5-2-u4-X21"},{"t":"「단점도 따져 봐야 실천할 때 문제가 적어.」","mis":"K5-2-u4-X21"},{"t":"「궁금한 점을 물어보면 의견이 더 단단해져.」","mis":"K5-2-u4-X17"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","맞장구만으로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#22','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C3',3,'mc','auto','의견 조정과 토의의 관계를 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X24','K5-2-u4-X01']::text[],false,'{"seq":22,"concept":"K5-2-u4-C3","difficulty":3,"kind":"mc","stem":"의견 조정과 토의의 관계를 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"토의에서 서로 다른 의견을 조정해 함께 받아들일 방법을 찾는다","correct":true},{"t":"토의에서 이긴 쪽 의견만 남긴다","mis":"K5-2-u4-X02"},{"t":"의견 조정은 토의와 관계없다","mis":"K5-2-u4-X24"},{"t":"의견이 다르면 토의를 멈춘다","mis":"K5-2-u4-X01"}],"explanation":["겨루지 않아요.","조정은 토의 안에 있어요.","함께 받아들일 방법을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#23','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C17',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 세 의견 가운데 하나를 골라 궁금한 점을 묻는 공손한 질문을 쓰고, 그 질문이 의견을 어떻게 다듬는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C17","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 세 의견 가운데 하나를 골라 궁금한 점을 묻는 공손한 질문을 쓰고, 그 질문이 의견을 어떻게 다듬는지 쓰세요.","answer_guide":{"answer":"예: 태린이의 의견에 「궁금해서 묻는데, 방학에는 누가 물을 줘?」라고 묻겠다. 이 질문에 답하려면 방학 동안 돌아가며 들르는 방법을 정해야 해서 당번 의견이 더 단단해진다.","scoring_points":["의견을 하나 골랐는가","공손한 질문을 썼는가","질문이 의견을 다듬는 점을 썼는가"]},"explanation":["의견을 골라요.","공손하게 물어요.","다듬어지는 점을 써요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#24','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C33',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 합의점을 실천하기 위해 누가 무엇을 언제 할지 실천 계획을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C33","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 합의점을 실천하기 위해 누가 무엇을 언제 할지 실천 계획을 쓰세요.","answer_guide":{"answer":"예: 다음 주 월요일까지 모둠마다 코팅한 이름표를 만들어 화분에 꽂고, 당번 표를 교실 뒤에 붙여 날마다 차례대로 물을 준다. 해가 필요한 화분은 창가로 옮기고, 한 주가 지나면 잘되었는지 함께 되돌아본다.","scoring_points":["누가 할지 썼는가","무엇을 할지 썼는가","언제 하고 어떻게 되돌아볼지 썼는가"]},"explanation":["누가예요.","무엇을이에요.","언제와 되돌아보기예요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_d#25','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C20',4,'essay','teacher','토의에서 내 의견이 뽑히지 않았던 경험이나 상황을 떠올려, 그때의 마음과 참여가 소중한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C20","difficulty":4,"kind":"essay","stem":"토의에서 내 의견이 뽑히지 않았던 경험이나 상황을 떠올려, 그때의 마음과 참여가 소중한 까닭을 쓰세요.","answer_guide":{"answer":"예: 모둠 토의에서 내 의견이 뽑히지 않아 처음에는 속상했다. 그런데 내가 한 질문 덕분에 모둠 의견의 빈틈이 메워졌다. 내 의견이 그대로 뽑히지 않아도 함께 말하고 고친 과정 속에 내 생각이 들어 있어 참여한 것이 소중하다.","scoring_points":["경험이나 상황을 떠올렸는가","그때의 마음을 썼는가","참여가 소중한 까닭을 썼는가"]},"explanation":["경험을 떠올려요.","마음을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
